-- Original runtime UMG view. Widgets are transient; gameplay data is read elsewhere.
-- All methods are called by main.lua's game-thread pump. No Blueprint buttons,
-- delegates, inventory writes, asset copies or background inventory scans.
local messages = require("paintmanager.i18n")
local languages = require("paintmanager.languages")
local t = messages.text
local player_messages = require("paintmanager.player_messages")
-- Retain keys only for shell text that outlives a language change. Dynamic
-- paint and preset rows are regenerated by their normal bounded render jobs.
local function caption(key, values) return { key = key, values = values } end
local safe = require("paintmanager.safe")
local paint_view = require("paintmanager.paint_view")
local transfer_quantity = require("paintmanager.transfer_quantity")
local collection = require("paintmanager.collection")
local presets = require("paintmanager.presets")
local json = require("paintmanager.json")
local plain_work = require("paintmanager.plain_work")
local processing = require("paintmanager.processing")
local clock_ms = require("paintmanager.work_budget").clock_ms
local M = {}
M.__index = M
local HOST_PACKAGE = "/Game/UI/Game/HUD/BP_VoyageIngameEmpty"
local HOST_ASSET = "BP_VoyageIngameEmpty_C"
local HOST_CLASS = HOST_PACKAGE .. "." .. HOST_ASSET
local SORTS = { "name_asc", "name_desc", "count_desc", "count_asc" }
local FILTER_KEYS = { all = "ui.filter.all", unlocked = "ui.filter.unlocked", locked = "ui.filter.locked",
    ready = "ui.filter.ready", insufficient = "ui.filter.insufficient" }
local SORT_KEYS = { name_asc = "ui.sort.name_asc", name_desc = "ui.sort.name_desc",
    count_desc = "ui.sort.count_desc", count_asc = "ui.sort.count_asc" }
local PAINT_TABS = { learned = true, ready = true, missing = true }
local TRANSFER_ICONS = { gather_paint = "to_backpack", gather_all = "to_backpack",
    return_paint = "to_box", return_all = "to_box" }
local PAINT_DETAIL_SIZE, PAINT_DETAIL_PADDING = 104, 6
-- Reserve frame/page/slot padding, the scrollbar, the check mark and its help button.
local SETTINGS_CHECKBOX_GUTTER = 176
local SHIP_RADIUS_DEFAULT, SHIP_RADIUS_MIN, SHIP_RADIUS_MAX = 3500, 3500, 5000
local function valid_ship_radius(value)
    return type(value) == "number" and value == value and value % 1 == 0
        and value >= SHIP_RADIUS_MIN and value <= SHIP_RADIUS_MAX
end
local PAGE_FILTERS = { learned = "unlocked", ready = "ready", missing = "insufficient" }
local PAGE_KEYS = { learned = "ui.tab.learned", ready = "ui.tab.ready", missing = "ui.tab.missing",
    presets = "ui.tab.presets", settings = "ui.tab.settings", debug = "ui.tab.debug" }

local C = {
    background = { R = 0.018, G = 0.024, B = 0.033, A = 0.99 },
    panel = { R = 0.033, G = 0.045, B = 0.059, A = 1 },
    paint_details = { R = 0.053, G = 0.083, B = 0.125, A = 1 },
    button = { R = 0.065, G = 0.105, B = 0.145, A = 1 },
    selected = { R = 0.10, G = 0.25, B = 0.28, A = 1 },
    text = { R = 0.90, G = 0.93, B = 0.96, A = 1 },
    muted = { R = 0.61, G = 0.68, B = 0.75, A = 1 },
    accent = { R = 0.34, G = 0.87, B = 0.77, A = 1 },
    warning = { R = 1, G = 0.74, B = 0.33, A = 1 },
    danger = { R = 0.30, G = 0.07, B = 0.08, A = 1 },
}

local function opaque_slate_color(red, green, blue)
    return { SpecifiedColor = { R = red, G = green, B = blue, A = 1 }, ColorUseRule = 0 }
end

-- Slate stores linear RGB. The comments give the corresponding sRGB colors.
local dropdown = {
    text = opaque_slate_color(0.88792, 0.90466, 0.92158),   -- #f2f4f6
    selected_text = opaque_slate_color(1, 1, 1),
    background = opaque_slate_color(0.01444, 0.01764, 0.02122), -- #202428
    hovered = opaque_slate_color(0.04231, 0.06125, 0.08438),    -- #3a4652
    selected = opaque_slate_color(0.00700, 0.10224, 0.28315),   -- #145a91
}

local function valid(object)
    local ok, result = pcall(function() return object ~= nil and object:IsValid() end)
    return ok and result == true
end

local function margin(value)
    return { Left = value, Top = value, Right = value, Bottom = value }
end

local function path_only(path)
    if type(path) ~= "string" then return nil end
    return path:match("^[^ ]+ (/.+)$") or path
end

local function current_controller()
    local pc = FindFirstOf("VoyagePlayerController")
    if not valid(pc) or not pc:IsLocalController() or not valid(pc.Pawn) then
        error(t("ui.error.player_unavailable"))
    end
    return pc
end

local function same_object(left, right)
    return valid(left) and valid(right) and left:GetAddress() == right:GetAddress()
end

local function context_key(pc)
    if not valid(pc) or not valid(pc.Pawn) then return nil end
    local world = pc:GetWorld()
    if not valid(world) then return nil end
    return tostring(pc:GetAddress()) .. ":" .. tostring(pc.Pawn:GetAddress()) .. ":" .. tostring(world:GetAddress())
end

local function current_context_key()
    local ok, key = pcall(function() return context_key(FindFirstOf("VoyagePlayerController")) end)
    return ok and key or nil
end

local function host_class()
    local class = StaticFindObject(HOST_CLASS)
    if not valid(class) then
        -- One exact UI asset, only on explicit open. The pinned GetAsset binding
        -- accepts const AssetData& and zero-initializes unspecified struct fields.
        local registry = StaticFindObject("/Script/AssetRegistry.Default__AssetRegistryHelpers")
        assert(valid(registry), t("ui.error.registry_unavailable"))
        class = registry:GetAsset({ PackageName = FName(HOST_PACKAGE, EFindName.FNAME_Add),
            AssetName = FName(HOST_ASSET, EFindName.FNAME_Add) })
    end
    assert(valid(class), t("ui.error.host_class_unavailable", { class = HOST_CLASS }))
    assert(class:IsA("/Script/CoreUObject.Class") and path_only(class:GetFullName()) == HOST_CLASS,
        t("ui.error.host_class_unexpected"))
    local parent = class
    for _ = 1, 16 do
        if path_only(parent:GetFullName()) == "/Script/UMG.UserWidget" then return class end
        parent = parent:GetSuperStruct()
        if not valid(parent) then break end
    end
    error(t("ui.error.host_not_userwidget"))
end

function M.new(config, callbacks)
    return setmetatable({ config = config, callbacks = callbacks or {}, open = false,
        buttons = {}, serial = 0, active_tab = "learned", model = nil, learning = false,
        preferences = { shipRadiusCm = SHIP_RADIUS_DEFAULT, paintTransferQuantity = transfer_quantity.default,
            depositSimilarAllColors = true, showDepositAllPaints = false,
            sort = "name_asc", lastPage = "learned", uiLanguage = "auto",
            showDeveloperTools = false, showNames = false, tileDensity = "comfortable" },
        favorites = {}, page_offset = 0, page_size = 128,
        view = { query = "", filter = "unlocked", sort = "name_asc" },
        status = { state = "done", message = t("ui.status.ready") } }, M)
end

-- Resize the owned canvas before applying the small-viewport fallback scale.
-- Ordinary viewports use their full logical area with a 12-unit edge margin.
-- These are expected bounds, not a claim about engine-arranged Slate geometry.
function M.fit_geometry(width, height, dpi)
    local function positive(value)
        return type(value) == "number" and value == value and value > 0 and value ~= math.huge
    end
    assert(positive(width) and positive(height) and positive(dpi), t("ui.error.viewport_invalid"))
    local logical_width, logical_height = width / dpi, height / dpi
    local available_width, available_height = logical_width - 24, logical_height - 24
    local scale = math.min(1, available_width / 900, available_height / 700)
    assert(scale > 0, t("ui.error.viewport_small"))
    return { scale = scale, logicalWidth = logical_width, logicalHeight = logical_height,
        left = 12, top = 12, width = available_width, height = available_height,
        layoutWidth = available_width / scale, layoutHeight = available_height / scale }
end

function M.grid_columns(width, density)
    local size = density == "compact" and 96 or 108
    -- Frame/page/scroll padding and the native vertical scrollbar stay outside
    -- the cells. Sparse grids get only their occupied columns, aligned left.
    return math.max(1, math.floor((width - 96) / (size + 8)))
end

function M:is_open() return self.open == true end
function M:is_closing() return self.open == true and self.escape_pending == true end
function M:is_connected() return not self.connection or self.connection.connected ~= false end

function M:_ship_radius_cm()
    -- Display the active connection radius when available, then the saved ship setting.
    local radius = self.connection and self.connection.radiusCm
    if type(radius) == "number" and radius == radius and radius > 0 and radius < math.huge then return radius end
    radius = self.preferences and self.preferences.shipRadiusCm
    return valid_ship_radius(radius) and radius or SHIP_RADIUS_DEFAULT
end

function M:_stock_radius_caption()
    return t("ui.stock.radius.scope", { meters = string.format("%.0f", self:_ship_radius_cm() / 100) })
end

function M:_sync_stock_total(model)
    if not valid(self.stock_total_label) then return end
    local bag = model and model.backpackPhysicalCount
    local boxes = model and not model.cachePreview and not model.learnedOnly and model.physicalCount or nil
    local total = bag and boxes and model.combinedPhysicalCount or nil
    local value = t("ui.value.unknown")
    if total and model.status == "captured" and model.stockComplete then value = tostring(total)
    elseif (bag or 0) + (boxes or 0) > 0 then value = t("ui.tile.lower_bound", { count = (bag or 0) + (boxes or 0) }) end
    local label = t("ui.stock.total", { count = value })
    if self.stock_total_caption ~= label then
        self:_set_text(self.stock_total_label, label)
        self.stock_total_caption = label
    end
end

-- Register the approved decoration only after signal loss. The shared icon
-- service owns bounded import/texture keepers; the shell owns this Image.
function M:_request_connection_illustration()
    if self:is_connected() or self.connection_illustration_requested or not self.icons
        or type(self.icons.bind_illustration) ~= "function" or not valid(self.connection_illustration) then return end
    local icons, image = self.icons, self.connection_illustration
    self.connection_illustration_requested = true
    local ok, ready, target, failure = pcall(icons.bind_illustration, icons, image, "signal_lost")
    if self.icons ~= icons or self.connection_illustration ~= image then
        if ok and target and type(icons.retire) == "function" then pcall(icons.retire, icons, target) end
        return
    end
    if ok then
        self.connection_illustration_target, self.connection_illustration_error = target, failure
    else self.connection_illustration_error = tostring(ready) end
end

-- The shell remains open without ship signal. The disconnected page owns its
-- return action independently from the retained paint pages.
local function connection_captions(connection, radius)
    local function known(value, allow_zero)
        return type(value) == "number" and value == value and value < math.huge
            and (allow_zero and value >= 0 or value > 0)
    end
    local distance = connection.distanceCm
    local distance_known = known(distance, true)
    local caption
    if distance_known then
        caption = t("ui.connection.distance", { distance = string.format("%.1f", distance / 100),
            radius = string.format("%.1f", radius / 100) })
    else caption = t("ui.connection.distance_unavailable", { radius = string.format("%.1f", radius / 100) }) end
    local descriptions = {
        ship_pending = "ui.connection.locating",
        ship_unavailable = "ui.connection.ship_unavailable",
        ship_ambiguous = "ui.connection.ship_ambiguous",
        ship_player_unavailable = "ui.connection.player_unavailable",
    }
    local description = descriptions[connection.code]
    -- A known outside distance justifies movement guidance. Unknown position
    -- or another connection failure should not ask an on-board player to move.
    if not description and distance_known and distance > radius then
        description = "ui.connection.description"
    end
    return caption, t(description or "ui.connection.unavailable")
end

function M:set_connection(connection)
    connection = connection or { connected = true }
    local was_connected = self:is_connected()
    local former_ship = self.connection and self.connection.shipOwnerId
    self.connection = { connected = connection.connected ~= false }
    for _, key in ipairs({ "reason", "code", "reasonCode", "distanceCm", "radiusCm", "distanceReference",
        "shipLocated", "shipOwnerId" }) do self.connection[key] = connection[key] end
    local connected = self:is_connected()
    if not connected and self.tab_click then self:_finish_tab_click(self.tab_click.tab, "disconnected") end
    if former_ship ~= self.connection.shipOwnerId or was_connected and not connected then
        self:set_presets(nil)
    end
    local caption, description = connection_captions(self.connection, self:_ship_radius_cm())
    if connected then caption, description = "", "" end
    local radius_caption = self:_stock_radius_caption(self.model)
    self:_request_connection_illustration()
    local applied = self.connection_presentation
    if applied and applied.panel == self.connection_panel and applied.connected == connected and applied.caption == caption
        and applied.radiusCaption == radius_caption and applied.description == description then
        return connected
    end
    if was_connected and not connected then
        self.jmap_armed = false
        self:_update_jmap()
        for _, button in ipairs(self.buttons or {}) do
            if not button.connection_close then button.release_required, button.pressed = true, false end
        end
    end
    if valid(self.connection_panel) then
        self.connection_panel:SetVisibility(connected and 1 or 0)
        self.content_panel:SetVisibility(connected and 0 or 1)
        for _, widget in ipairs(self.connection_actions or {}) do
            local visible = connected and (widget ~= self.debug_tab or self.preferences.showDeveloperTools)
            widget:SetVisibility(visible and (widget ~= self.preset_refresh_box or self.active_tab == "presets") and 0 or 1)
        end
        self:_set_text(self.connection_distance, caption)
        self:_set_text(self.connection_description, description)
        self:_set_text(self.stock_radius_label, radius_caption)
        self.connection_presentation = { panel = self.connection_panel, connected = connected, caption = caption,
            radiusCaption = radius_caption, description = description }
    end
    self:_sync_learn_all_enabled()
    if self.open and connected and not was_connected then
        self:_sync_preset_controls()
        if self.detail_row then self:_render_details(self.detail_row, self.model) end
    elseif self.open and not connected and self.detail_learn_control then
        self.detail_learn_control.widget:SetIsEnabled(false)
    end
    return connected
end

-- Called by the UE4SS shortcut. Set Lua state only; tick closes on the game
-- thread before polling layout, search or buttons.
function M:request_escape()
    if not self.open then return false end
    self.escape_pending = true
    return true
end

function M:_make(class_name)
    self.serial = self.serial + 1
    local class = StaticFindObject("/Script/UMG." .. class_name)
    assert(valid(class), t("ui.error.umg_class_unavailable", { class = class_name }))
    assert(valid(self.tree), t("ui.error.tree_construction"))
    local widget = StaticConstructObject(class, self.tree,
        FName("PaintManager_" .. class_name .. "_" .. self.serial), EObjectFlags.RF_Transient)
    assert(valid(widget), t("ui.error.widget_construction", { class = class_name }))
    return widget
end

function M:_text(value, size, color)
    local widget = self:_make("TextBlock")
    if type(value) == "table" then
        self.language_widgets = self.language_widgets or {}
        self.language_widgets[widget] = value
        value = t(value.key, value.values)
    end
    widget:SetText(FText(tostring(value or "")))
    widget:SetAutoWrapText(true)
    local font = widget.Font
    font.Size = size or 16
    widget:SetFont(font)
    widget:SetColorAndOpacity({ SpecifiedColor = color or C.text, ColorUseRule = 0 })
    return widget
end

function M:_label(value, size, color)
    local label = self:_text(value, size, color)
    label:SetAutoWrapText(false)
    label:SetTextOverflowPolicy(1) -- ETextOverflowPolicy.Ellipsis
    label:SetClipping(1) -- EWidgetClipping.ClipToBounds
    return label
end

local function editor_button(builder, key)
    local button = builder:_make("Button")
    button:SetBackgroundColor(C.selected)
    local label = builder:_label(caption(key), 16)
    label:SetJustification(1)
    button:SetContent(label)
    label.Slot:SetHorizontalAlignment(0)
    label.Slot:SetVerticalAlignment(2)
    label.Slot:SetPadding({ Left = 10, Top = 7, Right = 10, Bottom = 7 })
    return button, label
end

function M.make_editor_button(tree, serial, key)
    local builder = setmetatable({ tree = tree, serial = serial }, M)
    local button = editor_button(builder, key or "ui.button.open_paintmanager")
    return button, builder.serial, function() builder:_refresh_language_widgets() end
end

local function rounded_gray(brush, linear, radius)
    brush.DrawAs = 4 -- ESlateBrushDrawType.RoundedBox
    brush.TintColor = opaque_slate_color(linear, linear, linear)
    local outline = brush.OutlineSettings
    outline.RoundingType = 0 -- FixedRadius
    outline.CornerRadii = { X = radius, Y = radius, Z = radius, W = radius }
    outline.Width = 0
end

function M.make_deposit_button(tree, serial, key, stock_button, resources)
    local builder = setmetatable({ tree = tree, serial = serial }, M)
    local button = builder:_make("Button")
    button.IsFocusable = false
    local style = button.WidgetStyle
    style.NormalPadding, style.PressedPadding = margin(0), margin(0)
    style.Normal.DrawAs, style.Disabled.DrawAs = 0, 0
    rounded_gray(style.Hovered, 0.03434, 4) -- #343434
    rounded_gray(style.Pressed, 0.06480, 4) -- #484848

    local row = builder:_make("HorizontalBox")
    local tile = builder:_make("Border")
    rounded_gray(tile.Background, 0.78354, 5) -- #e5e5e5
    tile:SetPadding(margin(0))
    local image = builder:_make("Image")
    image:SetVisibility(1)
    local drawing = builder:_sized(image, 32, 32)
    tile:SetContent(drawing)
    drawing.Slot:SetHorizontalAlignment(2)
    drawing.Slot:SetVerticalAlignment(2)
    local tile_slot = row:AddChild(builder:_sized(tile, 42, 44))
    tile_slot:SetVerticalAlignment(2)

    local label = builder:_label(caption(key), 16, { R = 0.88792, G = 0.87962, B = 0.86316, A = 1 })
    local native_label = safe.get(stock_button, "MainTB")
    if valid(native_label) then
        label:SetFont(native_label.Font)
    else
        local font = label.Font
        font.TypefaceFontName = FName("Regular")
        label:SetFont(font)
    end
    local label_slot = row:AddChild(label)
    label_slot:SetVerticalAlignment(2)
    label_slot:SetPadding({ Left = 9, Top = 0, Right = 4, Bottom = 0 })
    button:SetContent(row)
    row.Slot:SetPadding(margin(0))
    row.Slot:SetHorizontalAlignment(1)
    row.Slot:SetVerticalAlignment(2)
    local release_icon = resources and resources:bind_deposit_icon(image)
    return button, builder.serial, release_icon, function() builder:_refresh_language_widgets() end
end

function M.make_editor_popup(tree, serial)
    local builder = setmetatable({ tree = tree, serial = serial }, M)
    local form = builder:_make("VerticalBox")
    builder:_add(form, builder:_label(caption("ui.editor.save_preset"), 20))
    local name_fields = builder:_make("VerticalBox")
    builder:_add(form, name_fields)
    builder:_add(name_fields, builder:_label(caption("ui.preset.name_hint"), 14))
    local entry = builder:_entry("ui.preset.name_hint")
    entry.SelectAllTextWhenFocused = true
    builder:_add(name_fields, builder:_sized(entry, nil, 38))
    local notice = builder:_text(t("ui.editor.checking"), 14, C.muted)
    builder:_add(form, notice)
    local buttons = builder:_make("HorizontalBox")
    local confirm = editor_button(builder, "ui.preset.save")
    local cancel, cancel_label = editor_button(builder, "ui.editor.cancel")
    builder:_add(buttons, confirm, true)
    builder:_add(buttons, cancel, true)
    builder:_add(form, buttons)
    local card = builder:_sized(builder:_border(form, C.panel, 16), 310)
    local shade = builder:_border(card, { R = 0, G = 0, B = 0, A = 0.58 }, 0)
    card.Slot:SetHorizontalAlignment(2)
    card.Slot:SetVerticalAlignment(2)
    name_fields:SetVisibility(1)
    confirm:SetVisibility(1)
    return { root = shade, name_fields = name_fields, entry = entry, notice = notice, confirm = confirm, cancel = cancel,
        cancel_label = cancel_label, refresh_language = function() builder:_refresh_language_widgets() end }, builder.serial
end

function M:_tooltip(widget, value)
    if not valid(widget) or type(value) ~= "string" and type(value) ~= "table" then return end
    -- A wrapping owned tooltip is bounded independently from its trigger.
    local text = self:_text(value, 14)
    -- Auto wrapping uses the allocated SizeBox width. WrapTextAt is reflected
    -- as a property, but the pinned dump exposes no callable setter.
    local box = self:_sized(text, 360)
    box:SetClipping(1)
    local tooltip = self:_border(box, C.background, 8)
    pcall(function() widget:SetToolTip(tooltip) end)
    return text
end

function M:_callback_error(detail)
    if self.callbacks.log then pcall(self.callbacks.log, "Player action failed: " .. tostring(detail)) end
    return player_messages.reason(detail)
end

function M:_set_text(widget, value)
    if valid(widget) then widget:SetText(FText(tostring(value or ""))) end
end

function M:_refresh_language_widgets()
    for widget, message in pairs(self.language_widgets or {}) do
        if valid(widget) then
            local value = FText(t(message.key, message.values))
            if message.hint then widget:SetHintText(value) else widget:SetText(value) end
        end
    end
end

function M:_sized(child, width, height)
    local box = self:_make("SizeBox")
    if width then box:SetWidthOverride(width) end
    if height then box:SetHeightOverride(height) end
    box:SetContent(child)
    return box
end

function M:_border(child, color, padding)
    local border = self:_make("Border")
    border:SetBrushColor(color or C.panel)
    border:SetPadding(margin(padding or 8))
    border:SetContent(child)
    return border
end

function M:_add(parent, child, fill)
    local slot = parent:AddChild(child)
    -- Size is present on horizontal/vertical slots; padding is cosmetic elsewhere.
    if fill then slot:SetSize({ Value = 1, SizeRule = 1 }) end
    pcall(function() slot:SetPadding(margin(4)) end)
    return slot
end

function M:_button(label, action, scope, color, icon_id, tooltip, icon_size, text_style)
    local widget = self:_make("Button")
    widget:SetBackgroundColor(color or C.button)
    local icon_only = icon_id == "star" or icon_id == "star_filled"
    local left = text_style and text_style.left
    local text = not icon_only and self:_label(label, text_style and text_style.size or 14) or nil
    if text then text:SetJustification(left and 0 or 1) end
    widget:SetClipping(1)
    icon_size = icon_size or 18
    local icon = not icon_only and icon_id and self.icons and self.icons:image(icon_id, icon_size)
    local icon_states
    local style = widget.WidgetStyle
    style.NormalPadding, style.PressedPadding = margin(0), margin(0)
    if icon_only then
        -- Remove the actual Slate brushes in every interaction state. A
        -- transparent background tint alone leaves the native outline.
        for _, state in ipairs({ "Normal", "Hovered", "Pressed", "Disabled" }) do
            style[state].DrawAs = 0 -- ESlateBrushDrawType.NoDrawType
        end
    end
    -- WidgetStyle is a native-reference wrapper. Mutate it before attachment;
    -- never pass the 912-byte FButtonStyle to SetStyle through the pinned
    -- UE4SS UFunction bridge's fixed 512-byte parameter buffer.
    local content
    if icon_only then
        -- Both states belong to the existing button from construction onward.
        -- Favorite clicks only change visibility; they never allocate widgets,
        -- request images, or wait for another grid render.
        local empty = self.icons and self.icons:image("star", 20)
        local filled = self.icons and self.icons:image("star_filled", 20)
        if not valid(empty) then empty = self:_label(t("ui.favorite.empty"), 14) end
        if not valid(filled) then filled = self:_label(t("ui.favorite.filled"), 14) end
        local states = self:_make("Overlay")
        states:AddChild(empty); states:AddChild(filled)
        local enabled = icon_id == "star_filled"
        empty:SetVisibility(enabled and 1 or 4)
        filled:SetVisibility(enabled and 4 or 1)
        icon_states = { empty = empty, filled = filled }
        content = self:_sized(states, 20, 20)
    else
        content = self:_make("HorizontalBox")
        if valid(icon) then
            local slot = content:AddChild(self:_sized(icon, icon_size, icon_size))
            slot:SetPadding({ Left = 0, Top = 0, Right = 6, Bottom = 0 })
            slot:SetVerticalAlignment(2)
        end
        -- Native ScaleToFit + DownOnly fits the actual remaining allocation,
        -- including changes to counts, DPI and window size, without guessing
        -- glyph widths or enlarging short labels.
        local fitted = self:_make("ScaleBox")
        fitted:SetStretch(2); fitted:SetStretchDirection(1)
        local text_slot = fitted:AddChild(text)
        text_slot:SetHorizontalAlignment(left and 1 or 2); text_slot:SetVerticalAlignment(2)
        local slot = content:AddChild(fitted)
        slot:SetSize({ Value = 1, SizeRule = 1 })
        slot:SetPadding(margin(0)); slot:SetVerticalAlignment(0)
    end
    widget:SetContent(content)
    local content_slot = content.Slot
    local padding = text_style and text_style.padding_x or 8
    content_slot:SetPadding(icon_only and margin(0) or { Left = padding, Top = 2, Right = padding, Bottom = 2 })
    content_slot:SetHorizontalAlignment(left and 1 or (icon_only or icon_size > 18) and 2 or 0)
    content_slot:SetVerticalAlignment(icon_only and 2 or 0)
    local tooltip_label = tooltip and self:_tooltip(widget, tooltip)
    local record = {
        widget = widget, label = text, scope = scope,
        pressed = false, icon_states = icon_states, tooltip_label = tooltip_label,
        favorite_enabled = icon_only and icon_id == "star_filled" or false,
    }
    self:_register_button(record, action)
    return widget
end

function M:_register_button(record, action)
    record.action = function(...)
        if self:is_connected() or record.connection_close then return action(...) end
    end
    self.buttons[#self.buttons + 1] = record
end

function M:_entry(hint_key)
    local widget = self:_make("EditableTextBox")
    -- Edit native fields before Slate construction. The reflected box style
    -- is 3200 bytes; only the small color fields and font size change.
    local style = widget.WidgetStyle
    style.TextStyle.Font.Size = 14
    local ink = { SpecifiedColor = { R = 0.006, G = 0.009, B = 0.013, A = 1 }, ColorUseRule = 0 }
    style.ForegroundColor = ink
    style.FocusedForegroundColor = ink
    style.ReadOnlyForegroundColor = ink
    style.TextStyle.ColorAndOpacity = ink
    style.BackgroundColor = { SpecifiedColor = { R = 1, G = 1, B = 1, A = 1 }, ColorUseRule = 0 }
    -- Slate applies its hint opacity and disabled effect to these base colors.
    -- Retain the native hover, focus and read-only background brushes.
    if hint_key then
        self.language_widgets = self.language_widgets or {}
        self.language_widgets[widget] = { key = hint_key, hint = true }
        widget:SetHintText(FText(t(hint_key)))
    end
    return widget
end

local function fill_dropdown_brush(brush, color)
    -- The native unselected brushes can start as NoDrawType.
    brush.DrawAs = 3 -- ESlateBrushDrawType.Image
    brush.TintColor = color
end

function M:_combo(row, options)
    local widget = self:_make("ComboBoxString")
    -- Style the popup rows before attachment. The closed button inherits its
    -- own dark foreground, and keyboard focus keeps its native outline.
    local style = widget.ItemStyle
    style.TextColor = dropdown.text
    style.SelectedTextColor = dropdown.selected_text
    for _, parity in ipairs({ "Even", "Odd" }) do
        fill_dropdown_brush(style[parity .. "RowBackgroundBrush"], dropdown.background)
        fill_dropdown_brush(style[parity .. "RowBackgroundHoveredBrush"], dropdown.hovered)
    end
    for _, state in ipairs({ "Active", "Inactive" }) do
        fill_dropdown_brush(style[state .. "Brush"], dropdown.selected)
        fill_dropdown_brush(style[state .. "HoveredBrush"], dropdown.selected)
    end
    for _, option in ipairs(options) do widget:AddOption(option) end
    -- Let Slate fit the selected caption and arrow together above the minimum.
    local box = self:_sized(widget, nil, 28)
    box:SetMinDesiredWidth(144)
    self:_add(row, box)
    return widget
end

function M:_request(command)
    if not self:is_connected() then return false end
    if command == "refresh" or not self.preferences.showDeveloperTools then return false end
    if command == "sources" then return false end
    local callback = self.callbacks.enqueue
    if not callback then error(t("ui.error.queue_unavailable")) end
    local accepted, message = callback(command)
    if accepted == false then
        self:set_status({ command = command, state = "error", message = message or t("ui.queue.rejected") })
    else
        self:set_status({ command = command, state = "queued", message = message or t("ui.queue.waiting") })
    end
end

-- Row actions belong to one render generation. Retire their polling records
-- immediately; detached controls cannot queue a grant or open obsolete details.
function M:_clear_learn_buttons()
    local retained = {}
    for _, button in ipairs(self.buttons) do
        if button == self.detail_learn_control or button.kind ~= "learn_recipe" and button.kind ~= "paint_select" and button.kind ~= "favorite" then retained[#retained + 1] = button end
    end
    self.buttons = retained
    if self.detail_learn_control then
        self.detail_learn_control.kind = "paint_detail"
        self.detail_learn_control.row = nil
        if valid(self.detail_learn_control.widget) then self.detail_learn_control.widget:SetIsEnabled(false) end
    end
end

function M:_paint_actions_pending()
    return self.waiting_stock or self.capture_patch ~= nil
end

local function transfer_caption(command, quantity)
    local key = "ui.transfer." .. command
    if command == "gather_paint" then key = quantity == "all" and "ui.transfer.gather_color" or "ui.transfer.gather_target" end
    local values = { quantity = quantity }
    return t(key, values), t(key .. "_help", values)
end

function M:_transfer_button(command, width, height, signal)
    local quantity = command == "gather_paint" and self.preferences.paintTransferQuantity or nil
    local label, help = transfer_caption(command, quantity)
    local button = self:_button(label, function() end, signal and "signal" or "paint", nil, TRANSFER_ICONS[command], nil, 22)
    local record = self.buttons[#self.buttons]
    record.transfer, record.signal, record.quantity, record.help = command, signal, quantity, help
    record.box = self:_sized(button, width, height)
    -- The parent remains hoverable when a backpack or journal read disables the action.
    record.tooltip_label = self:_tooltip(record.box, help)
    record.box:SetVisibility(1)
    button:SetIsEnabled(false)
    self.transfer_controls[#self.transfer_controls + 1] = record
    return record
end

function M:_transfer_availability(record)
    local state, model, row = self.transfer_state, self.model, self.detail_row
    local known = state and state.contextToken and type(state.backpack) == "table"
    local idle = known and self.open and not self.escape_pending and not self.learning and not state.busy and not state.unavailable
    local connected = self:is_connected()
    if record.signal then
        local shown = not connected and known and state.canReturnAll == true
        return shown, shown and idle
    end
    if not connected or not PAINT_TABS[self.active_tab] then return false, false end
    local same_model = known and model and model.contextToken == state.contextToken
    if record.transfer == "return_all" then return true, idle and (not model or same_model) and state.canReturnAll == true end
    local stock_ready = same_model and not self:_paint_actions_pending() and not model.cachePreview and not model.learnedOnly
    if record.transfer == "gather_all" then return true, stock_ready and idle and state.canGatherAll == true end
    local cache = self.active_paint_cache
    if not same_model or not cache or not cache.ready or not row or not row.id or self.selected_paint_id ~= row.id then
        return false, false
    end
    local backpack = state.backpack[row.id] or 0
    if record.transfer == "return_paint" then
        local tracked = backpack > 0 and state.returnable and (state.returnable[row.id] or 0) > 0
        return tracked, tracked and idle, row.id
    end
    local stocked = stock_ready and paint_view.stock_current(model, row) and type(row.count) == "number" and row.count > 0
    local target = self.preferences.paintTransferQuantity
    local needed = target == "all" or backpack < target
    return needed, needed and stocked and idle, row.id
end

function M:_sync_transfer_controls()
    if not self.transfer_controls then return end
    for _, record in ipairs(self.transfer_controls) do
        local shown, enabled, id = self:_transfer_availability(record)
        shown, enabled = shown == true, enabled == true
        if shown ~= record.shown then record.box:SetVisibility(shown and 0 or 1) end
        if enabled ~= record.enabled then record.widget:SetIsEnabled(enabled) end
        local state, generation = self.transfer_state, self.render_generation
        local quantity = record.transfer == "gather_paint" and self.preferences.paintTransferQuantity or nil
        local quantity_changed = record.quantity ~= quantity
        if quantity_changed then
            local label, help = transfer_caption(record.transfer, quantity)
            self:_set_text(record.label, label)
            record.quantity, record.help = quantity, help
        end
        if enabled ~= record.enabled or id ~= record.item_id or quantity_changed then
            record.release_required = record.release_required or record.pressed
        end
        local rebind = id ~= record.item_id or generation ~= record.generation or state ~= record.state or quantity_changed
        record.shown, record.enabled, record.item_id = shown, enabled, id
        if rebind then
            record.generation, record.state = generation, state
            local function action()
                if record.action ~= action or self.transfer_state ~= state or self.render_generation ~= generation
                    or self.context_key ~= current_context_key() then return end
                local visible, allowed, current_id = self:_transfer_availability(record)
                if not visible or not allowed or current_id ~= id then return end
                self:set_learning(true)
                local ok, accepted, message, status_handled = pcall(self.callbacks.transfer_paint, record.transfer, id)
                if not ok or accepted == false then
                    self:set_learning(false)
                    self:set_status({ command = record.transfer, state = "error", message = ok and (message or t("ui.queue.rejected")) or self:_callback_error(accepted) })
                elseif not status_handled then
                    self:set_status({ command = record.transfer, state = "queued", message = message or t("ui.queue.waiting") })
                end
            end
            record.action = action
        end
        local reason = state and (state.unavailableKey and t(state.unavailableKey) or state.unavailable)
        if record.unavailable ~= reason or quantity_changed then
            record.unavailable = reason
            self:_set_text(record.tooltip_label, reason or record.help)
        end
    end
    if self.detail_backpack then
        local row, state = self.detail_row, self.transfer_state
        local known = state and self.model and state.contextToken == self.model.contextToken and type(state.backpack) == "table"
        local label = row and (known and t("ui.transfer.backpack_count", {count = state.backpack[row.id] or 0})
            or state and (state.unavailableKey and t(state.unavailableKey) or state.unavailable) or t("ui.transfer.backpack_loading")) or ""
        if self.backpack_caption ~= label then self:_set_text(self.detail_backpack, label); self.backpack_caption = label end
    end
end

function M:update_backpack_counts(token, counts)
    local model = self.model
    if not model or model.contextToken ~= token then return end
    counts = counts or false
    if self.capture_patch or self.stock_patch_job or self.stock_patch_pending then
        self.pending_backpack = {token = token, counts = counts}
        return
    end
    self.pending_backpack = nil
    local before = model.backpackCounts
    if before == counts then return end
    if type(before) == "table" and counts then
        local changed = false
        for id, n in pairs(counts) do if before[id] ~= n then changed = true; break end end
        if not changed then for id in pairs(before) do if counts[id] == nil then changed = true; break end end end
        if not changed then return end
    end
    paint_view.set_backpack_counts(model, counts)
    if self.open then self:_queue_render(model, true, false, true)
    elseif self.reopen_view then self.reopen_view.projection = nil end
end

function M:set_transfer_state(state)
    if self.transfer_state and (not state or self.transfer_state.contextToken ~= state.contextToken) then
        self.last_transfer_line, self.last_transfer_status = nil, nil
        if TRANSFER_ICONS[self.status.command] then self.status = { state = "done", message = t("ui.status.ready") } end
        self:_render_status()
    end
    self.transfer_state = state
    self:_sync_transfer_controls()
end

function M:set_learning(active)
    self.learning = active == true
    for _, button in ipairs(self.buttons) do
        if button.kind == "learn_recipe" and valid(button.widget) then
            button.widget:SetIsEnabled(not self.learning and not self:_paint_actions_pending() and self:is_connected()
                and self.active_paint_cache ~= nil and self.active_paint_cache.ready == true and button.generation == self.render_generation
                and paint_view.learn_eligible(self.model, button.row))
        end
    end
    self:_sync_learn_all_enabled()
    self:_sync_preset_controls()
end

local learn_eligible = paint_view.learn_eligible

-- Bound copied search state without splitting a UTF-8 code point. Search is a
-- literal display-name match; asset IDs and Lua patterns are never queried.
local function bounded_query(value)
    if #value <= 256 then return value end
    local cut = 257
    while cut > 1 and value:byte(cut) >= 128 and value:byte(cut) < 192 do cut = cut - 1 end
    return value:sub(1, cut - 1)
end

function M:_sync_view_controls()
    for tab, button in pairs(self.tab_controls or {}) do
        if valid(button.widget) then button.widget:SetBackgroundColor(tab == self.active_tab and C.selected or C.button) end
    end
    if self.sort_control then
        self:_set_text(self.sort_control.label, t("ui.sort.caption", { name = t(SORT_KEYS[self.view.sort]) }))
    end
    if self.settings_sort_control then
        self:_set_text(self.settings_sort_control.label, t("ui.sort.caption", { name = t(SORT_KEYS[self.view.sort]) }))
    end
    if self.density_control then
        self:_set_text(self.density_control.label, t("ui.settings.density_value", {
            value = t(self.preferences.tileDensity == "compact" and "ui.settings.compact" or "ui.settings.comfortable") }))
    end
    if valid(self.search_box) and self.last_search_text ~= self.view.query then
        self.search_box:SetText(FText(self.view.query))
        self.last_search_text = self.view.query
    end
end

function M:set_view(options)
    if self.open and not self:is_connected() then return false end
    options = options or {}
    local query = options.query == nil and self.view.query or options.query
    local filter, sort = options.filter or self.view.filter, options.sort or self.view.sort
    if type(query) ~= "string" or not FILTER_KEYS[filter] or not SORT_KEYS[sort] then return false end
    query = bounded_query(query)
    if query == self.view.query and filter == self.view.filter and sort == self.view.sort then
        -- A longer paste can have the same bounded prefix as the current query.
        -- Keep the native field identical to the query actually being applied.
        if self.last_search_text ~= query then self:_sync_view_controls() end
        return true
    end
    self.view = { query = query, filter = filter, sort = sort }
    self.page_offset = 0
    self:_sync_view_controls()
    -- Filtering only consumes the completed plain capture. It does not queue a
    -- scan or change the all-ready batch scope. Retire stale actions immediately.
    self:_queue_render(self.model, self.full_render_model ~= nil and self.full_render_model == self.model)
    return true
end

function M:_poll_search()
    if not self:is_connected() or not PAINT_TABS[self.active_tab] or not valid(self.search_box) then return end
    local value = safe.text(self.search_box:GetText())
    assert(value ~= nil, t("ui.error.search_text"))
    self.last_search_text = value
    if value ~= self.view.query then self:set_view({ query = value }) end
end

function M:_cycle_sort()
    for index, sort in ipairs(SORTS) do
        if sort == self.view.sort then self:_change_settings({ sort = SORTS[index % #SORTS + 1] }); return end
    end
end

function M:_sync_learn_all_enabled()
    self:_sync_transfer_controls()
    local button = self.learn_all_control
    if not button or not valid(button.widget) then return end
    button.widget:SetIsEnabled(self.open and self:is_connected() and not self.learning and not self:_paint_actions_pending() and self.model and self.model.stockComplete == true
        and self.model.cachePreview ~= true
        and (self.learn_all_ready_count or 0) > 0
        and button.generation == self.render_generation and button.model == self.model)
end

function M:_set_learn_all_ready(model, generation, count)
    self.learn_all_ready_count = count or 0
    local button = self.learn_all_control
    if not button then return end
    local token, view_context = model and model.contextToken or nil, self.context_key
    button.generation, button.model = generation, model
    -- The polling record belongs to this model/generation even though the
    -- toolbar's native button is retained for the whole window lifetime.
    button.action = function() self:_request_learning_all(generation, model, token, view_context) end
    self:_sync_learn_all_enabled()
end

function M:_request_learning_all(generation, model, token, view_context)
    if not self:is_connected() or not self.open or not PAINT_TABS[self.active_tab] or self.learning or self:_paint_actions_pending() or generation ~= self.render_generation or self.model ~= model
        or not self.active_paint_cache or not self.active_paint_cache.ready
        or not model or model.contextToken ~= token or model.status ~= "captured" or model.stockComplete ~= true or model.cachePreview == true
        or (self.learn_all_ready_count or 0) < 1 or view_context ~= self.context_key
        or view_context ~= current_context_key() then return end
    local callback = self.callbacks.learn_all
    if type(callback) ~= "function" then
        self:set_status({ command = "learn_all", state = "error", reasonKey = "ui.learn_all.unavailable" })
        return
    end
    self:set_learning(true)
    local ok, accepted, message = pcall(callback)
    if not ok or accepted == false then
        self:set_learning(false)
        self:set_status({ command = "learn_all", state = "error", message = ok and
            (message or t("ui.queue.rejected")) or t("ui.learn.failed", { error = self:_callback_error(accepted) }) })
    else
        self:set_status({ command = "learn_all", state = "queued", message = message or t("ui.learn_all.queued") })
    end
end

function M:_request_learning(item_id, generation)
    if not self:is_connected() or not self.open or not PAINT_TABS[self.active_tab] or self.learning or self:_paint_actions_pending() or generation ~= self.render_generation then return end
    if not self.active_paint_cache or not self.active_paint_cache.ready then return end
    local entry = self.visible_tiles_by_id and self.visible_tiles_by_id[item_id]
    if not entry or not learn_eligible(self.model, entry.row) then return end
    local callback = self.callbacks.learn_recipe
    if type(callback) ~= "function" then
        self:set_status({ command = "learn_recipe", state = "error", reasonKey = "ui.learn.unavailable" })
        return
    end
    -- Set the gate before the callback, whose native status work may recurse
    -- into the scheduler. Only the controller performs validation and writes.
    self:set_learning(true)
    local ok, accepted, message, terminal = pcall(callback, item_id)
    if not ok or accepted == false then
        self:set_learning(false)
        self:set_status({ command = "learn_recipe", state = "error", message = ok and
            (message or t("ui.queue.rejected")) or t("ui.learn.failed", { error = self:_callback_error(accepted) }) })
    elseif terminal == true then
        self:set_learning(false)
        self:set_status({ command = "learn_recipe", state = "done", message = message or "" })
    else
        self:set_status({ command = "learn_recipe", state = "queued", message = message or t("ui.learn.queued") })
    end
end

function M:_select_paint(item_id, generation)
    if not self:is_connected() or not self.open or not PAINT_TABS[self.active_tab] or generation ~= self.render_generation or not self.model then return end
    if not self.active_paint_cache or not self.active_paint_cache.ready then return end
    local entry = self.visible_tiles_by_id and self.visible_tiles_by_id[item_id]
    if not entry or entry.generation ~= generation then return end
    if self.selected_paint_id == item_id and self.detail_row == entry.row then return end
    self:_render_details(entry.row, self.model)
end

function M:_finish_tab_click(tab, outcome, cached, learned_prefix)
    local click = self.tab_click
    if not click or click.tab ~= tab then return end
    self.tab_click = nil
    local now = clock_ms()
    local elapsed = click.started and now and now >= click.started and string.format("%.0f", now - click.started) or "unavailable"
    pcall(self.callbacks.log, string.format("Tab click: tab=%s; elapsedMs=%s; outcome=%s; cached=%s%s",
        t(PAGE_KEYS[tab]), elapsed, outcome, tostring(cached == true), learned_prefix and "; source=learned_prefix" or ""))
end

function M:_paint_page_shown(cache, cached)
    if not self.tab_click or self.tab_click.tab ~= cache.tab or self.active_tab ~= cache.tab
        or self.active_paint_cache ~= cache then return end
    local result, model = cache.result, self.model
    -- A cold shell and stock tabs projected from just the Vault are placeholders.
    if not cache.ready or not result or not model or result.model ~= model then return end
    if model.learnedOnly and (cache.tab ~= "learned" or result.visible_count == 0 and model.recipeCatalogComplete ~= true) then return end
    local outcome = result.visible_count > 0 and "list"
        or cache.tab == "missing" and result.checking_count > 0 and "checking" or "empty"
    self:_finish_tab_click(cache.tab, outcome, cached, model.learnedOnly)
end

function M:_tab_load_stopped()
    local click, status = self.tab_click, self.status
    if not click or not status or status.state ~= "error" and status.state ~= "cancelled" then return end
    if status.command == "preset_refresh" and click.tab == "presets" and not self.preset_view
        or status.command == "toggle" and PAINT_TABS[click.tab] and (not self.model or self.model.learnedOnly) then
        self:_finish_tab_click(click.tab, status.state, false)
    end
end

function M:_select_tab(tab, clicked)
    if clicked and (not self.open or self.escape_pending) then return false end
    if self.open and not self:is_connected() and not self.restoring_preferences then return false end
    if tab == "paint" then tab = "learned" end
    if tab == "diagnostics" then tab = "debug" end
    if not (PAINT_TABS[tab] or tab == "settings" or tab == "debug" or tab == "presets") then return false end
    if tab == "debug" and not self.preferences.showDeveloperTools then return false end
    local changed = self.active_tab ~= tab
    local measure = clicked and self.open and self.callbacks.log
    local started = measure and clock_ms()
    if self.tab_click and (measure or changed) then self:_finish_tab_click(self.tab_click.tab, "superseded") end
    if measure then self.tab_click = { tab = tab, started = started } end
    -- A click on even the already visible default page outranks a late
    -- storage publication for the rest of this window.
    local manual = self.open and not self.restoring_preferences
    local first_click = manual and not self.manual_page
    if manual then self.manual_page = true end
    if changed and self.active_tab == "debug" and self.processing_built then self:_processing_update_draft() end
    self.active_tab = tab
    if valid(self.preset_refresh_box) then self.preset_refresh_box:SetVisibility(tab == "presets" and self:is_connected() and 0 or 1) end
    self.jmap_armed = false
    if not PAINT_TABS[tab] and self.render_job then
        self.render_generation = (self.render_generation or 0) + 1
        self.render_job = nil
    end
    local controls_cached = tab == "settings" or tab == "debug" and self.debug_built
    if tab == "presets" and not self.preset_list then self:_build_presets(); self:_queue_preset_render() end
    if tab == "debug" then
        if not self.debug_built then self:_build_debug()
        elseif changed and self.debug_section == "diagnostics" then self:_processing_refresh() end
    end
    if valid(self.switcher) then
        self.switcher:SetActiveWidgetIndex(PAINT_TABS[tab] and 0 or ({ settings = 1, debug = 2, presets = 3 })[tab])
        if tab == "settings" or tab == "debug" then self:_finish_tab_click(tab, "controls", controls_cached)
        elseif tab == "presets" and self.preset_page_outcome then self:_finish_tab_click(tab, self.preset_page_outcome, true) end
    end
    if PAINT_TABS[tab] then
        self.view.filter = PAGE_FILTERS[tab]
        if changed then self:_activate_paint_tab(tab)
        elseif self.active_paint_cache then self:_paint_page_shown(self.active_paint_cache, true) end
    end
    if manual and tab ~= "debug" then
        if self.pending_page then
            self.pending_page.tab = tab
        elseif (changed or first_click or self.preferences.lastPage ~= tab) and self:_persist_setting_change({ lastPage = tab }, true) then
            self.preferences.lastPage = tab
        end
    end
    if valid(self.stock_toolbar) then self.stock_toolbar:SetVisibility(tab == "debug" and 1 or 0) end
    if self.learn_all_control and valid(self.learn_all_control.widget) then self.learn_all_control.widget:SetVisibility(PAINT_TABS[tab] and 0 or 1) end
    if self.preset_controls then self:_sync_preset_controls() end
    self:_sync_view_controls()
    self:_update_jmap()
    self:_sync_transfer_controls()
    self:_tab_load_stopped()
    return true
end

local function favorite_key(row)
    if type(row.assetType) == "string" and row.assetType ~= "" and type(row.assetName) == "string" and row.assetName ~= "" then
        return row.assetType .. "\0" .. row.assetName
    end
end

function M:_persist_setting_change(changes, defer_page)
    if self.restoring_preferences or type(self.callbacks.change_settings) ~= "function" then return true end
    local ok, accepted, message, reason = pcall(self.callbacks.change_settings, changes)
    if ok and accepted == false and defer_page and reason == "preferences_loading" then
        self.pending_page = { tab = changes.lastPage, context = self.context_key }
        return false
    end
    if not ok or accepted == false then
        self:set_status({ state = "error", message = message or (ok and t("ui.queue.rejected") or self:_callback_error(accepted)) })
        return false
    end
    return true
end

function M:flush_page_choice()
    local pending = self.pending_page
    self.pending_page = nil
    if not pending or not self.open or self:is_closing() or not self:is_connected() or pending.tab ~= self.active_tab
        or pending.context ~= self.context_key or pending.context ~= current_context_key() then return end
    if self.preferences.lastPage ~= pending.tab and self:_persist_setting_change({ lastPage = pending.tab }) then
        self.preferences.lastPage = pending.tab
    end
end

function M:_change_settings(changes)
    if not self:is_connected() or type(changes) ~= "table" then return false end
    if changes.uiLanguage ~= nil and not languages.valid(changes.uiLanguage) then return false end
    if changes.shipRadiusCm ~= nil and not valid_ship_radius(changes.shipRadiusCm) then return false end
    if changes.paintTransferQuantity ~= nil and not transfer_quantity.valid(changes.paintTransferQuantity) then return false end
    if not self:_persist_setting_change(changes) then return false end
    if changes.lastPage ~= nil then self.pending_page = nil end
    local settings = {}
    for key, value in pairs(self.preferences) do settings[key] = value end
    for key, value in pairs(changes) do settings[key] = value end
    self:set_preferences(settings, self.favorites, changes.lastPage ~= nil)
    return true
end

function M:_sync_favorite_controls(identity)
    for _, button in ipairs(self.buttons) do
        if button.kind == "favorite" and button.generation == self.render_generation
            and button.favorite_key and (identity == nil or button.favorite_key == identity) then
            local enabled = self.favorites[button.favorite_key] == true
            if button.favorite_enabled ~= enabled and valid(button.widget) then
                button.favorite_enabled = enabled
                if button.icon_states then
                    button.icon_states.empty:SetVisibility(enabled and 1 or 4)
                    button.icon_states.filled:SetVisibility(enabled and 4 or 1)
                end
                self:_set_text(button.label, t(enabled and "ui.favorite.filled" or "ui.favorite.empty"))
                self:_set_text(button.tooltip_label, t(enabled and "ui.favorite.remove" or "ui.favorite.add"))
            end
        end
    end
end

function M:set_preferences(settings, favorites, explicit_page)
    settings = type(settings) == "table" and settings or {}
    local next_preferences = {
        uiLanguage = languages.valid(settings.uiLanguage) and settings.uiLanguage or "auto",
        shipRadiusCm = valid_ship_radius(settings.shipRadiusCm) and settings.shipRadiusCm
            or valid_ship_radius(self.preferences.shipRadiusCm) and self.preferences.shipRadiusCm or SHIP_RADIUS_DEFAULT,
        paintTransferQuantity = transfer_quantity.valid(settings.paintTransferQuantity) and settings.paintTransferQuantity
            or transfer_quantity.default,
        depositSimilarAllColors = settings.depositSimilarAllColors ~= false,
        showDepositAllPaints = settings.showDepositAllPaints == true,
        sort = SORT_KEYS[settings.sort] and settings.sort or self.view.sort,
        lastPage = settings.lastPage or self.preferences.lastPage or "learned",
        showNames = settings.showNames == true,
        tileDensity = settings.tileDensity == "compact" and "compact" or "comfortable",
        showDeveloperTools = settings.showDeveloperTools == true,
    }
    local normalized, favorites_changed, order_changed = {}, false, false
    for key, value in pairs(type(favorites) == "table" and favorites or {}) do
        if type(value) == "table" then
            local identity = favorite_key(value)
            if identity then normalized[identity] = value.enabled == true end
        elseif type(key) == "string" then normalized[key] = value == true end
    end
    for key, value in pairs(normalized) do if self.favorites[key] ~= value then favorites_changed = true end end
    for key, value in pairs(self.favorites) do if normalized[key] ~= value then favorites_changed = true end end
    for key, value in pairs(normalized) do if (self.favorites[key] == true) ~= (value == true) then order_changed = true end end
    for key, value in pairs(self.favorites) do if (normalized[key] == true) ~= (value == true) then order_changed = true end end
    local previous, changed = self.preferences, false
    for key, value in pairs(next_preferences) do if previous[key] ~= value then changed = true end end
    self.preferences, self.favorites, self.view.sort = next_preferences, normalized, next_preferences.sort
    if order_changed then self.favorite_order_revision = (self.favorite_order_revision or 0) + 1 end
    if favorites_changed then self:_sync_favorite_controls() end
    -- Optimistic preference publications and their later save receipts update
    -- stars in place. Favorites affect sorting only at the next normal render.
    if not changed and not explicit_page then return end
    self.restoring_preferences = true
    if valid(self.debug_tab) then
        self.debug_tab:SetVisibility(self:is_connected() and next_preferences.showDeveloperTools and 0 or 1)
    end
    if not next_preferences.showDeveloperTools then
        self.jmap_armed = false
        if self.active_tab == "debug" then self:_select_tab("settings") end
        if previous.showDeveloperTools and self.debug_built then
            local retained = {}
            for _, button in ipairs(self.buttons) do if button.scope ~= "debug" then retained[#retained + 1] = button end end
            self.buttons = retained
            self.debug_page:ClearChildren()
            self:_release_debug()
            if valid(self.close_button) then self.close_button:SetKeyboardFocus() end
        end
    end
    for key, record in pairs(self.checkboxes or {}) do
        if valid(record.widget) then record.widget:SetIsChecked(next_preferences[key] == true); record.checked = next_preferences[key] == true end
    end
    if (explicit_page or not self.manual_page and next_preferences.lastPage ~= previous.lastPage) and
        (PAINT_TABS[next_preferences.lastPage] or next_preferences.lastPage == "settings" or next_preferences.lastPage == "presets") then
        if self.root then self:_select_tab(next_preferences.lastPage) else self.active_tab = next_preferences.lastPage end
    end
    self.restoring_preferences = false
    self:_sync_language_choice()
    self:_sync_view_controls()
    self:_update_jmap()
    if previous.shipRadiusCm ~= next_preferences.shipRadiusCm then
        self:_sync_ship_radius_controls()
        self:set_connection(self.connection)
    end
    if previous.paintTransferQuantity ~= next_preferences.paintTransferQuantity then
        self:_sync_transfer_settings()
        self:_sync_transfer_controls()
    end
    -- Last-page publication is already handled by _select_tab. Developer
    -- visibility/radius metadata do not change any paint tile. Rebuilding here
    -- used to restart the same projection a second time for one tab click.
    if previous.sort ~= next_preferences.sort or previous.showNames ~= next_preferences.showNames
        or previous.tileDensity ~= next_preferences.tileDensity then
        self.page_offset = 0
        if previous.tileDensity ~= next_preferences.tileDensity then self.grid_column_count = nil end
        self:_queue_render(self.model, true)
    end
end

function M:_toggle_favorite(row, generation)
    if not self:is_connected() or not self.open or not PAINT_TABS[self.active_tab] or generation ~= self.render_generation then return end
    if not self.active_paint_cache or not self.active_paint_cache.ready then return end
    local key = favorite_key(row)
    if not key or type(self.callbacks.favorite) ~= "function" then return end
    local enabled = self.favorites[key] ~= true
    local ok, accepted, message = pcall(self.callbacks.favorite, row.assetType, row.assetName, enabled)
    if not ok or accepted == false then
        self:set_status({ state = "error", message = message or (ok and t("ui.queue.rejected") or self:_callback_error(accepted)) })
        return
    end
    if not self.open or generation ~= self.render_generation then return end
    if (self.favorites[key] == true) ~= enabled then self.favorite_order_revision = (self.favorite_order_revision or 0) + 1 end
    self.favorites[key] = enabled
    self:_sync_favorite_controls(key)
end

function M:_update_jmap()
    if not self.debug_jmap or not valid(self.jmap_confirm) then return end
    self:_set_text(self.debug_jmap.label, t(self.jmap_armed and "ui.button.jmap_confirm" or "ui.button.jmap_prepare"))
    self.jmap_confirm:SetBackgroundColor(self.jmap_armed and C.danger or C.button)
    self.jmap_notice:SetVisibility(self.jmap_armed and 0 or 1)
end

local PRESET_LIMIT, PRESET_THUMBNAILS = 64, 5
local PRESET_NAME_WIDTH = 245

local function preset_zone_label(zone)
    return zone.displayName or t("ui.preset.logical_zone", {
        material = zone.materialSlotName, part = zone.partName })
end

function M:_preset_target(view)
    for _, target in ipairs(view.targets or {}) do
        if target.kind == self.preset_kind and (target.kind == "character"
            or self.connection and self.connection.shipOwnerId and target.ownerRuntimeRef
                and target.ownerRuntimeRef.id == self.connection.shipOwnerId) then
            return target
        end
    end
end

function M:_preset_selection()
    local projection = self.preset_projection
    local entry = projection and projection.by_id[self.selected_preset_id]
    return projection and projection.target, entry and entry.preset, entry and entry.state
end

function M:_sync_preset_controls()
    local _, preset, state = self:_preset_selection()
    local view, controls = self.preset_view or {}, self.preset_controls or {}
    local projection = self.preset_projection
    local available = self:is_connected() and not self.learning and not self.preset_reconciling
    local library_ready = projection ~= nil and view.library ~= nil and view.error == nil
    local can_save = library_ready and projection.can_save
    local detail_ready = self.preset_detail_ready == true
    local enabled = {
        ship = available, character = available, refresh = self.active_tab ~= "presets" or available, import = available,
        save = available and can_save and #view.library.presets < PRESET_LIMIT,
        apply = available and library_ready and detail_ready and (state == "fill" or state == "replace"),
        delete = available and library_ready and detail_ready and preset ~= nil,
    }
    for name, button in pairs(controls) do
        local wanted = enabled[name] == true
        if wanted ~= button.preset_enabled and valid(button.widget) then
            button.widget:SetIsEnabled(wanted)
            button.preset_enabled = wanted
        end
    end
    if controls.ship then controls.ship.widget:SetBackgroundColor(self.preset_kind == "boat" and C.selected or C.button) end
    if controls.character then controls.character.widget:SetBackgroundColor(self.preset_kind == "character" and C.selected or C.button) end
    if valid(self.preset_save_row) then self.preset_save_row:SetVisibility(can_save and 0 or 1) end
    if valid(self.preset_delete_box) then self.preset_delete_box:SetVisibility(preset and detail_ready and 0 or 1) end
    local rows_enabled = available and projection ~= nil
    for _, button in pairs(self.preset_rows or {}) do
        if rows_enabled ~= button.preset_enabled and valid(button.widget) then
            button.widget:SetIsEnabled(rows_enabled)
            button.preset_enabled = rows_enabled
        end
    end
end

function M:needs_preset_refresh()
    return self.open and self.active_tab == "presets" and self:is_connected()
        and not self.preset_view and not self.preset_auto_requested
end

function M:mark_preset_refresh_requested()
    self.preset_auto_requested = true
end

function M:_preset_action(command, generation, shell)
    if not self:is_connected() or not self.open or self.active_tab ~= "presets" or self.learning
        or self.preset_reconciling or generation ~= self.preset_generation or shell ~= self.preset_shell_generation
        or self.context_key ~= current_context_key() then return end
    local target, preset, state = self:_preset_selection()
    local view, projection = self.preset_view or {}, self.preset_projection
    local callback = self.callbacks[command]
    local arguments = {}
    if command == "preset_save" then
        if not target or not projection.can_save or view.error or #view.library.presets >= PRESET_LIMIT
            or not valid(self.preset_name_box) then return end
        local name = safe.text(self.preset_name_box:GetText())
        if name == nil then error(t("ui.preset.name_read_error")) end
        arguments = { target.id, name }
    elseif command == "preset_apply" then
        if not target or (state ~= "fill" and state ~= "replace") or view.error or not self.preset_detail_ready then return end
        arguments = { target.id, preset.id }
    elseif command == "preset_delete" then
        if not preset or view.error or not self.preset_detail_ready then return end
        arguments = { preset.id }
    end
    if type(callback) ~= "function" then
        self:set_status({ command = command, state = "error", reasonKey = "ui.preset.unavailable" })
        return
    end
    -- Share the existing action gate before any callback can reenter the pump.
    self:set_learning(true)
    local ok, accepted, message = pcall(callback, table.unpack(arguments))
    if not ok or accepted == false then
        self:set_learning(false)
        self:set_status({ command = command, state = "error", message = ok and
            (message or t("ui.queue.rejected")) or t("ui.preset.failed", { error = self:_callback_error(accepted) }) })
    else
        if command == "preset_refresh" then self:mark_preset_refresh_requested() end
        if command == "preset_save" then
            self.preset_pending = self:_border(self:_label(t("ui.preset.saving", { name = arguments[2] }), 15), C.button, 6)
            self:_add(self.preset_list, self.preset_pending)
            self.preset_scroll:ScrollToEnd()
            self.preset_notice:SetVisibility(1)
        end
        self:set_status({ command = command, state = "queued", message = message or t("ui.preset.queued") })
    end
end

function M:_choose_preset_type(kind, shell)
    if not self:is_connected() or not self.open or self.active_tab ~= "presets" or self.learning
        or self.preset_reconciling or shell ~= self.preset_shell_generation or kind == self.preset_kind then return end
    self.preset_kind = kind
    self:_set_text(self.preset_name_box, "")
    self:_queue_preset_render()
end

function M:_select_preset(id, generation)
    local projection = self.preset_projection
    if not self:is_connected() or not self.open or self.active_tab ~= "presets" or self.learning
        or self.preset_reconciling or generation ~= self.preset_generation or not projection or not projection.by_id[id]
        or id == self.selected_preset_id then return end
    local old = self.preset_rows[self.selected_preset_id]
    if old then old.widget:SetBackgroundColor(C.button) end
    self.selected_preset_id = id
    self.preset_selected_ids[self.preset_kind] = id
    self.preset_rows[id].widget:SetBackgroundColor(C.selected)
    self:_queue_preset_details(projection)
end

function M:_build_presets()
    self.preset_shell_generation = (self.preset_shell_generation or 0) + 1
    local shell = self.preset_shell_generation
    local page, controls = self:_make("VerticalBox"), {}
    self.preset_controls = controls
    self.preset_kind = self.preset_kind or "boat"
    self.preset_selected_ids = self.preset_selected_ids or {}

    local target_bar = self:_make("HorizontalBox")
    for _, entry in ipairs({ { "ship", "boat", "ui.preset.type.ship" },
        { "character", "character", "ui.preset.type.character" } }) do
        local name, kind, label = entry[1], entry[2], entry[3]
        local button = self:_button(caption(label), function() self:_choose_preset_type(kind, shell) end, "presets")
        controls[name] = self.buttons[#self.buttons]
        self:_add(target_bar, self:_sized(button, 130, 36))
    end
    self:_add(target_bar, self:_make("HorizontalBox"), true)
    local import = self:_button(caption("ui.storage.import"), function()
        self:_preset_action("preset_import", self.preset_generation, shell)
    end, "presets", nil, "import")
    controls.import = self.buttons[#self.buttons]
    controls.refresh = self.preset_refresh_control
    self:_add(target_bar, self:_sized(import, 115, 36))
    self:_add(page, target_bar)

    self.preset_notice = self:_text("", 14, C.muted)
    self:_add(page, self.preset_notice)
    local heading = self:_make("HorizontalBox")
    self.preset_summary = self:_label("", 15)
    self:_add(heading, self:_sized(self.preset_summary, PRESET_NAME_WIDTH))
    self.preset_heading_zones = self:_make("HorizontalBox")
    self:_add(heading, self.preset_heading_zones, true)
    self:_add(page, heading)
    self.preset_list = self:_make("VerticalBox")
    local scroll = self:_make("ScrollBox")
    scroll:AddChild(self.preset_list)
    self.preset_scroll = scroll
    self:_add(page, scroll, true)

    local save_bar = self:_make("HorizontalBox")
    self:_add(save_bar, self:_label(caption("ui.preset.save_current"), 15))
    self.preset_save_icons = self:_make("HorizontalBox")
    self:_add(save_bar, self.preset_save_icons)
    self.preset_name_box = self:_entry("ui.preset.name_hint")
    self:_add(save_bar, self:_sized(self.preset_name_box, nil, 36), true)
    local save = self:_button(caption("ui.preset.save"), function()
        self:_preset_action("preset_save", self.preset_generation, shell)
    end, "presets", nil, "save")
    controls.save = self.buttons[#self.buttons]
    self:_add(save_bar, self:_sized(save, 110, 36))
    self.preset_save_row = self:_border(save_bar, C.button, 4)
    self:_add(page, self.preset_save_row)

    local details = self:_make("HorizontalBox")
    self.preset_icon_box = self:_make("VerticalBox")
    self.preset_icon_box:SetClipping(1)
    self.preset_preview_box = self:_sized(self:_border(self.preset_icon_box, C.background, 2), PAINT_DETAIL_SIZE, PAINT_DETAIL_SIZE)
    self:_add(details, self.preset_preview_box):SetVerticalAlignment(0)
    local meta = self:_make("VerticalBox")
    self.preset_detail_title = self:_label(t("ui.preset.choose_saved"), 18)
    self:_add(meta, self.preset_detail_title)
    self.preset_detail_host = self:_make("SizeBox")
    self:_add(meta, self.preset_detail_host, true)
    self.preset_detail_note = self:_label("", 14, C.muted)
    self:_add(meta, self.preset_detail_note)
    self:_add(details, meta, true):SetVerticalAlignment(0)
    local apply = self:_button(caption("ui.preset.apply"), function()
        self:_preset_action("preset_apply", self.preset_generation, shell)
    end, "presets", C.selected, "apply", caption("ui.preset.apply_help"), 56)
    controls.apply = self.buttons[#self.buttons]
    self.preset_apply_box = self:_sized(apply, self.preset_action_width or 300)
    apply.Slot:SetHorizontalAlignment(0); apply.Slot:SetVerticalAlignment(0)
    local apply_slot = details:AddChild(self.preset_apply_box)
    apply_slot:SetVerticalAlignment(0)
    apply_slot:SetPadding({ Left = 4, Top = 0, Right = 4, Bottom = 0 })
    self.preset_details_box = self:_sized(self:_border(details, C.paint_details, PAINT_DETAIL_PADDING),
        nil, PAINT_DETAIL_SIZE + 2 * PAINT_DETAIL_PADDING)
    self:_add(page, self.preset_details_box)
    local delete = self:_button(caption("ui.preset.delete"), function()
        self:_preset_action("preset_delete", self.preset_generation, shell)
    end, "presets", nil, "delete", caption("ui.preset.delete_help"))
    controls.delete = self.buttons[#self.buttons]
    self.preset_delete_box = self:_sized(delete, 110, 32)
    self:_add(page, self.preset_delete_box):SetHorizontalAlignment(3)
    if self.render_persistence then self.persistence_message = self.render_persistence() end
    self.persistence_label = self:_text(self.persistence_message or "", 13, C.muted)
    self.persistence_label:SetVisibility(self.persistence_message and 0 or 1)
    self:_add(page, self.persistence_label)
    self.presets_host:SetContent(page)
    self:_sync_preset_controls()
end

function M:set_persistence(message, render)
    self.persistence_message, self.render_persistence = message, render
    if valid(self.persistence_label) then
        self:_set_text(self.persistence_label, message)
        self.persistence_label:SetVisibility(message and 0 or 1)
    end
end

function M:_remove_pending_preset()
    if valid(self.preset_pending) then self.preset_pending:RemoveFromParent() end
    self.preset_pending = nil
    if self.preset_projection and not next(self.preset_projection.by_id) and valid(self.preset_notice) then
        self.preset_notice:SetVisibility(0)
    end
end

function M:set_preset_save_error(message, render)
    self:_remove_pending_preset()
    self.render_preset_error = render
    if self.preset_view then self.preset_view.error = message end
    self:_set_text(self.preset_notice, message)
    if valid(self.preset_notice) then self.preset_notice:SetVisibility(0) end
    self:_sync_preset_controls()
end

function M:set_presets(view, saved_id, base_snapshot)
    if self.preset_view ~= view then self.render_preset_error = nil end
    if view and view.error and view ~= self.preset_view and self.callbacks.log then
        pcall(self.callbacks.log, "Preset view error: " .. tostring(view.error))
    end
    self:_remove_pending_preset()
    local same_library = base_snapshot and self.preset_view and base_snapshot == self.preset_view.storageSnapshot
    self.preset_view = view
    if not view then self.preset_auto_requested = nil end
    if view and saved_id and self.preset_projection and valid(self.preset_list) then
        if self:_reconcile_saved_preset(view, saved_id, same_library) then return end
    end
    self:_queue_preset_render()
end

function M:_queue_preset_render()
    self.preset_generation = (self.preset_generation or 0) + 1
    self.preset_page_outcome = nil
    self.preset_render_job, self.preset_projection, self.preset_detail_ready = nil, nil, false
    self.preset_reconciling = nil
    self.preset_rows = {}
    local retained = {}
    for _, button in ipairs(self.buttons) do
        if button.kind ~= "preset_select" then retained[#retained + 1] = button end
    end
    self.buttons = retained
    self:_sync_preset_controls()
    if not valid(self.preset_list) then return end
    self.preset_list:SetVisibility(2)
    self.preset_details_box:SetVisibility(2)
    self:_set_text(self.preset_notice, t("ui.render.building"))
    local view = self.preset_view or {}
    local records = view.library and view.library.presets or {}
    local target = self:_preset_target(view)
    self.preset_render_job = {
        generation = self.preset_generation, phase = "prepare", index = 1, completed = 0,
        total = 2 * math.min(PRESET_LIMIT, #records) + 8,
        records = records, entries = {}, by_id = {}, icons = {}, target = target, can_save = false,
    }
end

function M:_preset_page_shown(job, outcome)
    if not self.open or self.preset_generation ~= job.generation then return end
    self.preset_page_outcome = outcome
    self:_finish_tab_click("presets", outcome, false)
end

function M:_preset_paint(zone, cache)
    local paint = zone.paint
    if paint == json.null then return t("ui.preset.empty_zone"), nil, true end
    if type(paint) ~= "table" then return t("ui.preset.unknown_zone") end
    local key = favorite_key(paint)
    if not key then return t("ui.paint.name_unavailable") end
    if not cache[key] then
        local icon_path, name = collection.loaded_paint_icon(paint.assetType, paint.assetName)
        cache[key] = { icon_path = icon_path, name = name }
    end
    local row = cache[key]
    -- Older saved presets contain a display-name string without its language.
    return row.name or (not languages.game_tag and paint.displayName) or t("ui.paint.name_unavailable"), row.icon_path
end

function M:_preset_thumbnail(zone, cache)
    local name, icon_path, empty = self:_preset_paint(zone, cache)
    local texture = self:_paint_texture(icon_path)
    local widget
    if texture then
        widget = self:_make("Image")
        if not pcall(function() widget:SetBrushFromTexture(texture, false) end) then widget = nil end
    end
    if not widget then
        local fallback = self:_label(t(empty and "ui.preset.empty_thumbnail" or "ui.value.unknown"), 14, C.muted)
        fallback:SetJustification(1)
        widget = self:_border(fallback, C.background, 2)
        fallback.Slot:SetVerticalAlignment(2)
    end
    self:_tooltip(widget, t("ui.preset.zone", { zone = preset_zone_label(zone), paint = name }))
    return widget
end

local function same_preset_columns(left, right)
    if #left ~= #right then return false end
    for index, zone in ipairs(left) do
        if zone.materialSlotName ~= right[index].materialSlotName or zone.partName ~= right[index].partName then return false end
    end
    return true
end

function M:_build_preset_row(entry, job)
    local id, generation = entry.preset.id, job.generation
    local current = entry.state == "match"
    local row = self:_make("Button")
    row:SetBackgroundColor(id == self.selected_preset_id and C.selected or C.button)
    row:SetClipping(1)
    row.WidgetStyle.NormalPadding, row.WidgetStyle.PressedPadding = margin(0), margin(0)
    local content = self:_make("HorizontalBox")
    local stripe = self:_border(self:_make("HorizontalBox"), current and C.accent or C.button, 0)
    content:AddChild(self:_sized(stripe, 4)):SetVerticalAlignment(0)
    local identity = self:_make("HorizontalBox")
    local name = presets.display_name(entry.preset, job.records)
    local title = self:_label(name, 15)
    local name_tooltip = self:_tooltip(title, name)
    self:_add(identity, title, true):SetVerticalAlignment(2)
    local current_label = self:_label(t("ui.preset.matches_current"), 13, C.accent)
    current_label:SetVisibility(current and 0 or 1)
    self:_add(identity, self:_sized(current_label, 64)):SetVerticalAlignment(2)
    self:_add(content, self:_sized(identity, PRESET_NAME_WIDTH - 8)):SetVerticalAlignment(0)
    local shared_labels = same_preset_columns(entry.zones, job.heading_zones)
    for index = 1, math.min(#entry.zones, PRESET_THUMBNAILS) do
        local zone = entry.zones[index]
        local cell = self:_make("VerticalBox")
        local picture = self:_sized(self:_preset_thumbnail(zone, job.icons), 42, 42)
        cell:AddChild(picture):SetHorizontalAlignment(2)
        if not shared_labels then
            local caption = self:_label(preset_zone_label(zone), 12, C.muted)
            caption:SetJustification(1)
            cell:AddChild(caption)
        end
        self:_add(content, cell, true):SetVerticalAlignment(2)
    end
    if #entry.zones > PRESET_THUMBNAILS then
        self:_add(content, self:_label(t("ui.preset.more_zones", { count = #entry.zones - PRESET_THUMBNAILS }), 13))
            :SetVerticalAlignment(2)
    end
    row:SetContent(content)
    content.Slot:SetPadding(margin(0))
    content.Slot:SetHorizontalAlignment(0); content.Slot:SetVerticalAlignment(0)
    local wrapper = self:_sized(row, nil, shared_labels and 56 or 66)
    self:_add(self.preset_list, wrapper)
    local record = { widget = row, label = title, current_label = current_label, stripe = stripe, wrapper = wrapper,
        name_tooltip = name_tooltip, display_name = name, shared_labels = shared_labels, scope = "presets",
        kind = "preset_select", generation = generation, id = id, preset_enabled = false }
    self:_register_button(record, function() self:_select_preset(id, generation) end)
    self.preset_rows[id] = record
    row:SetIsEnabled(record.preset_enabled)
end

local PRESET_DETAIL_KEYS = {
    match = "ui.preset.already_applied", fill = "ui.preset.can_fill", replace = "ui.preset.can_replace",
    incompatible = "ui.preset.incompatible", unknown = "ui.preset.current_unknown",
}

function M:_remove_preset_row(id)
    local button = self.preset_rows[id]
    if not button then return end
    button.wrapper:RemoveFromParent()
    for index, item in ipairs(self.buttons) do
        if item == button then table.remove(self.buttons, index); break end
    end
    self.preset_rows[id], self.preset_projection.by_id[id] = nil, nil
end

local function same_preset_thumbnails(previous, current)
    if #previous ~= #current then return false end
    for index = 1, math.min(#current, PRESET_THUMBNAILS) do
        local a, b = previous[index], current[index]
        if a.materialSlotName ~= b.materialSlotName or a.partName ~= b.partName or a.displayName ~= b.displayName
            or a.paint.assetType ~= b.paint.assetType or a.paint.assetName ~= b.paint.assetName
            or a.paint.displayName ~= b.paint.displayName then return false end
    end
    return true
end

function M:_patch_preset_row(record, job)
    local id, projection = record.id, self.preset_projection
    local old, button = projection.by_id[id], self.preset_rows[id]
    local entry = { preset = record, state = presets.compare_layout(job.target, record),
        zones = presets.ordered_zones(self.preset_kind, record.zones) }
    if button and (not same_preset_thumbnails(old.zones, entry.zones)
        or button.shared_labels ~= same_preset_columns(entry.zones, job.heading_zones)) then
        self:_remove_preset_row(id)
        button = nil
    end
    if not button then
        self:_build_preset_row(entry, job)
    else
        if old.state ~= entry.state then
            button.current_label:SetVisibility(entry.state == "match" and 0 or 1)
            button.stripe:SetBrushColor(entry.state == "match" and C.accent or C.button)
        end
        local name = presets.display_name(record, job.records)
        if name ~= button.display_name then
            self:_set_text(button.label, name)
            self:_set_text(button.name_tooltip, name)
            button.display_name = name
        end
    end
    projection.by_id[id] = entry
end

function M:_reconcile_saved_preset(view, saved_id, same_library)
    local projection, target = self.preset_projection, self:_preset_target(view)
    if not target or not projection.target or target.id ~= projection.target.id then return false end
    local records = view.library.presets
    local saved, seen, count = nil, {}, 0
    for _, record in ipairs(records) do
        if record.target.kind == self.preset_kind then
            if record.id == saved_id then saved = record end
            seen[record.id], count = true, count + 1
        end
    end
    if not saved then return false end
    local heading = presets.ordered_zones(self.preset_kind, target.logicalZones)
    -- The storage coordinator verified the exact bytes of both displayed
    -- sources. When the freshly read target also matches, existing rows keep
    -- their classification and detail widgets.
    local same_target = same_library and same_preset_columns(heading, projection.heading_zones)
        and presets.compare_layout(projection.target, saved) == "match"
    if not same_preset_columns(heading, projection.heading_zones) then
        self.preset_heading_zones:ClearChildren()
        for index = 1, math.min(#heading, PRESET_THUMBNAILS) do
            local label = self:_label(preset_zone_label(heading[index]), 13, C.muted)
            label:SetJustification(1)
            self:_add(self.preset_heading_zones, label, true)
        end
    end
    local job = { phase = "saved_rows", saved_id = saved_id, generation = self.preset_generation,
        records = records, target = target, icons = projection.icons, heading_zones = heading,
        index = 1, completed = 0, total = #records + 2, projection = projection }
    self.preset_reconciling = not same_target
    projection.target, projection.can_save, projection.heading_zones = target, false, heading
    self:_patch_preset_row(saved, job)
    for id in pairs(projection.by_id) do if not seen[id] then self:_remove_preset_row(id) end end
    if self.selected_preset_id and not seen[self.selected_preset_id] then
        self.selected_preset_id, self.preset_selected_ids[self.preset_kind] = nil, nil
    end
    self:_set_text(self.preset_summary, t("ui.preset.saved", { count = count }))
    self.preset_notice:SetVisibility(1)
    self.preset_page_outcome = nil
    if same_target then
        local name = saved.name:lower()
        for id, entry in pairs(projection.by_id) do
            if id ~= saved_id and entry.preset.name:lower() == name then
                local button = self.preset_rows[id]
                local title = presets.display_name(entry.preset, records)
                self:_set_text(button.label, title)
                self:_set_text(button.name_tooltip, title)
                button.display_name = title
                if id == self.selected_preset_id then self:_set_text(self.preset_detail_title, title) end
            end
        end
        self:_preset_page_shown(job, "list")
    else self.preset_render_job = job end
    self:_sync_preset_controls()
    return true
end

function M:_queue_preset_details(projection)
    self.preset_detail_ready = false
    self.preset_details_box:SetVisibility(2)
    self.preset_render_job = { phase = "detail_clear", generation = self.preset_generation,
        projection = projection, completed = 0, total = 2 + #(projection.by_id[self.selected_preset_id].zones) }
    self:_sync_preset_controls()
end

function M:_advance_preset_render(job)
    if job.phase == "saved_rows" then
        local record = job.records[job.index]
        if record then
            if record.id ~= job.saved_id and record.target.kind == self.preset_kind then self:_patch_preset_row(record, job) end
            job.index = job.index + 1
        else
            self.preset_reconciling = nil
            self:_preset_page_shown(job, "list")
            job.phase = "detail_clear"
        end
    elseif job.phase == "prepare" then
        local preset = job.index <= PRESET_LIMIT and job.records[job.index]
        if preset then
            if preset.target.kind == self.preset_kind then
                local state = presets.compare_layout(job.target, preset)
                local entry = { preset = preset, state = state, zones = presets.ordered_zones(self.preset_kind, preset.zones) }
                job.entries[#job.entries + 1], job.by_id[preset.id] = entry, entry
                if state == "match" then job.has_match = true end
                if state == "unknown" then job.layout_unknown = true end
            end
            job.index = job.index + 1
        else job.phase = "heading" end
    elseif job.phase == "heading" then
        self.preset_list:ClearChildren()
        self.preset_heading_zones:ClearChildren()
        local id = self.preset_selected_ids[self.preset_kind]
        self.selected_preset_id = job.by_id[id] and id or nil
        self.preset_selected_ids[self.preset_kind] = self.selected_preset_id
        local view = self.preset_view
        job.can_save = view ~= nil and view.error == nil and view.library ~= nil
            and job.target ~= nil and job.target.complete == true and not job.has_match and not job.layout_unknown
        local notice = not view and t("ui.preset.initial") or view.error and self.render_preset_error and self.render_preset_error()
            or view.error and t("ui.preset.library_error", { error = player_messages.reason(view.error, "main.reason.storage") })
            or (not job.target or not job.target.complete) and t("ui.preset.current_unknown")
            or #job.entries == 0 and t("ui.preset.none_saved")
        self:_set_text(self.preset_notice, notice or "")
        self.preset_notice:SetVisibility(notice and 0 or 1)
        if #job.entries == 0 and view and (view.library or view.error) then
            self:_preset_page_shown(job, view.error and "error" or "empty")
        end
        self:_set_text(self.preset_summary, t("ui.preset.saved", { count = #job.entries }))
        job.heading_zones = job.target and job.target.logicalZones
            and presets.ordered_zones(self.preset_kind, job.target.logicalZones)
            or job.entries[1] and job.entries[1].zones or {}
        for index = 1, math.min(#job.heading_zones, PRESET_THUMBNAILS) do
            local label = self:_label(preset_zone_label(job.heading_zones[index]), 13, C.muted)
            label:SetJustification(1)
            self:_add(self.preset_heading_zones, label, true)
        end
        job.phase, job.index = "rows", 1
    elseif job.phase == "rows" then
        local entry = job.entries[job.index]
        if entry then
            self:_build_preset_row(entry, job)
            job.index = job.index + 1
        else job.phase = "save" end
    elseif job.phase == "save" then
        self.preset_save_icons:ClearChildren()
        if job.can_save then
            for index = 1, math.min(#job.heading_zones, PRESET_THUMBNAILS) do
                self:_add(self.preset_save_icons, self:_sized(self:_preset_thumbnail(job.heading_zones[index], job.icons), 22, 22))
            end
        end
        self.preset_projection = { target = job.target, by_id = job.by_id, icons = job.icons,
            can_save = job.can_save, heading_zones = job.heading_zones }
        self.preset_list:SetVisibility(0)
        if #job.entries > 0 then self:_preset_page_shown(job, "list") end
        self:_sync_preset_controls()
        job.projection, job.phase = self.preset_projection, "detail_clear"
    elseif job.phase == "detail_clear" then
        self.preset_icon_box:ClearChildren()
        job.detail = job.projection.by_id[self.selected_preset_id]
        local entry = job.detail
        local rows = math.ceil((entry and #entry.zones or 0) / 2)
        local grid = self:_make("UniformGridPanel")
        self.preset_detail_zones = grid
        if rows > 3 then
            local overflow = self:_make("ScrollBox")
            overflow:AddChild(grid)
            self.preset_detail_host:SetContent(overflow)
        else
            self.preset_detail_host:SetContent(grid)
        end
        self.preset_details_box:SetHeightOverride(2 * PAINT_DETAIL_PADDING
            + math.max(PAINT_DETAIL_SIZE, 68 + 24 * math.min(rows, 3)))
        self.preset_preview_box:SetVisibility(entry and 0 or 1)
        self.preset_apply_box:SetVisibility(entry and 0 or 1)
        self:_set_text(self.preset_detail_title, entry and presets.display_name(entry.preset,
            self.preset_view.library.presets) or t("ui.preset.choose_saved"))
        self:_set_text(self.preset_detail_note, entry and t(PRESET_DETAIL_KEYS[entry.state]) or "")
        job.phase, job.index = "detail_zones", 1
    elseif job.phase == "detail_zones" then
        local zone = job.detail and job.detail.zones[job.index]
        if zone then
            local label = self:_label(t("ui.preset.zone", {
                zone = preset_zone_label(zone), paint = self:_preset_paint(zone, job.projection.icons) }), 14)
            local position = job.index - 1
            local slot = self.preset_detail_zones:AddChildToUniformGrid(label, math.floor(position / 2), position % 2)
            slot:SetHorizontalAlignment(0)
            if job.index <= PRESET_THUMBNAILS then
                if position % 2 == 0 then
                    job.mosaic_row = self:_make("HorizontalBox")
                    local mosaic_slot = self.preset_icon_box:AddChild(job.mosaic_row)
                    mosaic_slot:SetSize({ Value = 1, SizeRule = 1 })
                    mosaic_slot:SetPadding(margin(1))
                end
                local image_slot = job.mosaic_row:AddChild(self:_preset_thumbnail(zone, job.projection.icons))
                image_slot:SetSize({ Value = 1, SizeRule = 1 })
                image_slot:SetPadding(margin(1)); image_slot:SetHorizontalAlignment(0); image_slot:SetVerticalAlignment(0)
            end
            job.index = job.index + 1
        else
            self.preset_detail_ready = job.detail ~= nil
            self.preset_details_box:SetVisibility(0)
            self:_sync_preset_controls()
            job.phase = "done"
        end
    end
end

function M:_help_button(row, message, scope, show)
    local widget = self:_button("?", show, scope, nil, nil, message)
    self:_add(row, self:_sized(widget, 34, 32)):SetVerticalAlignment(2)
    return self.buttons[#self.buttons]
end

function M:_setting_control(row, widget, min_width)
    local box = self:_sized(widget, nil, 34)
    box:SetMinDesiredWidth(min_width)
    self:_add(row, box):SetVerticalAlignment(2)
end

function M:_add_setting(page, row, key)
    local help_key = "ui.settings.help." .. key
    local message = caption(help_key)
    local help = self:_text(message, 15, C.accent)
    help:SetVisibility(1)
    self:_help_button(row, message, "settings", function()
        if self.active_tab ~= "settings" or page ~= self.settings_page then return end
        local previous = self.settings_help_text
        if valid(previous) then previous:SetVisibility(1) end
        self.settings_help_text = previous ~= help and help or nil
        if self.settings_help_text then help:SetVisibility(0) end
    end)
    local slot = self:_add(page, row)
    self:_add(page, help)
    return slot
end

function M:_checkbox(parent, key, message_key)
    local row = self:_make("HorizontalBox")
    local widget = self:_make("CheckBox")
    local checked = self.preferences[key] == true
    widget:SetIsChecked(checked)
    local caption_box = self:_sized(self:_text(caption(message_key), 16))
    widget:SetContent(caption_box)
    -- Keep help beside short captions. When space runs out, the checkbox
    -- gets the remaining width and its wrapped text determines the row height.
    self:_add(row, widget, true):SetVerticalAlignment(2)
    self:_add_setting(parent, row, key):SetHorizontalAlignment(1)
    self.checkboxes[key] = { widget = widget, caption_box = caption_box, checked = checked, scope = "settings" }
end

function M:_sync_ship_radius_controls()
    local radius = self.preferences.shipRadiusCm
    for cm, record in pairs(self.ship_radius_controls or {}) do
        local selected = cm == radius
        if selected ~= record.ship_radius_selected and valid(record.widget) then
            record.widget:SetBackgroundColor(selected and C.selected or C.button)
            record.ship_radius_selected = selected
        end
    end
end

function M:_sync_transfer_settings()
    if not self.quantity_controls then return end
    local quantity = self.preferences.paintTransferQuantity
    for value, record in pairs(self.quantity_controls) do
        local selected = value == quantity
        record.widget:SetBackgroundColor(selected and C.selected or C.button)
    end
    local custom = not self.quantity_controls[quantity]
    self.quantity_apply.widget:SetBackgroundColor(custom and C.selected or C.button)
    self:_set_text(self.quantity_entry, custom and tostring(quantity) or "")
end

function M:_build_transfer_settings(page)
    self:_add(page, self:_text(caption("ui.settings.paint_transfers"), 18))
    self:_checkbox(page, "depositSimilarAllColors", "ui.settings.deposit_similar_all_colors")
    self:_checkbox(page, "showDepositAllPaints", "ui.settings.show_deposit_all_paints")
    local row = self:_make("WrapBox")
    self:_add(row, self:_text(caption("ui.settings.backpack_target"), 16)):SetVerticalAlignment(2)
    self.quantity_controls = {}
    local function apply(value)
        if not self.open or self:is_closing() or not self:is_connected() or self.active_tab ~= "settings"
            or self.settings_page ~= page or self.context_key ~= current_context_key() then return end
        if value == nil then
            local ok, entry = pcall(function() return safe.text(self.quantity_entry:GetText()) end)
            local digits = ok and type(entry) == "string" and entry:match("^%s*([0-9]+)%s*$")
            value = digits and tonumber(digits)
            if not transfer_quantity.valid(value) then
                self:set_status({ state = "error", reasonKey = "ui.settings.invalid_backpack_target",
                    reasonValues = { maximum = transfer_quantity.maximum } })
                return
            end
        end
        if value ~= self.preferences.paintTransferQuantity then self:_change_settings({ paintTransferQuantity = value }) end
    end
    for _, value in ipairs({ 1, 5, "all" }) do
        local label = value == "all" and caption("ui.settings.all_cans") or tostring(value)
        local button = self:_button(label, function() apply(value) end, "settings")
        self.quantity_controls[value] = self.buttons[#self.buttons]
        self:_setting_control(row, button, 50)
    end
    self.quantity_entry = self:_entry("ui.settings.custom_cans")
    local custom = self:_make("HorizontalBox")
    self:_setting_control(custom, self.quantity_entry, 160)
    local button = self:_button(caption("ui.settings.apply_quantity"), function() apply() end, "settings")
    self.quantity_apply = self.buttons[#self.buttons]
    self:_setting_control(custom, button, 82)
    row:AddChild(custom)
    self:_add_setting(page, row, "quantity")
    self:_sync_transfer_settings()
end

function M:_sync_language_choice()
    for code, button in pairs(self.language_choices or {}) do
        button:SetBackgroundColor(code == self.preferences.uiLanguage and C.selected or C.button)
    end
end

function M:_build_language_choice(page)
    local row = self:_make("WrapBox")
    self:_add(row, self:_text(caption("ui.settings.language"), 16)):SetVerticalAlignment(2)
    self.language_choices = {}
    for _, code in ipairs(languages.choices) do
        local label = code == "auto" and caption("ui.settings.language_auto") or messages.language_name(code)
        local button = self:_button(label, function()
            if self.preferences.uiLanguage ~= code then self:_change_settings({uiLanguage = code}) end
        end, "settings")
        self.language_choices[code] = button
        self:_setting_control(row, button, code == "auto" and 190 or 112)
    end
    self:_add_setting(page, row, "language")
    self:_sync_language_choice()
end

function M:_build_settings()
    local page = self.settings_page
    self:_build_language_choice(page)
    self.checkboxes = {}
    self:_checkbox(page, "showNames", "ui.settings.names")
    self:_checkbox(page, "showDeveloperTools", "ui.settings.developer")
    local density = self:_make("WrapBox")
    self:_setting_control(density, self:_button(t("ui.settings.density"), function()
        self:_change_settings({ tileDensity = self.preferences.tileDensity == "compact" and "comfortable" or "compact" })
    end, "settings"), 260)
    self.density_control = self.buttons[#self.buttons]
    self:_add_setting(page, density, "density")
    local sort = self:_make("WrapBox")
    self:_setting_control(sort, self:_button(t("ui.settings.sort"), function() self:_cycle_sort() end,
        "settings", nil, "sort"), 260)
    self.settings_sort_control = self.buttons[#self.buttons]
    self:_add_setting(page, sort, "sort")
    local ship_radius = self:_make("WrapBox")
    self.ship_radius_controls = {}
    self:_add(ship_radius, self:_text(caption("ui.settings.ship_radius"), 16)):SetVerticalAlignment(2)
    for _, meters in ipairs({ 35, 40, 45, 50 }) do
        local cm = meters * 100
        local button = self:_button(caption("ui.button.radius", { meters = meters }), function()
            if self.preferences.shipRadiusCm ~= cm then self:_change_settings({ shipRadiusCm = cm }) end
        end, "settings")
        self.ship_radius_controls[cm] = self.buttons[#self.buttons]
        self:_setting_control(ship_radius, button, 95)
    end
    self:_add_setting(page, ship_radius, "ship_radius")
    self:_sync_ship_radius_controls()
    if self.transfer_controls then self:_build_transfer_settings(page) end
end


function M:_update_diagnostics()
    if not valid(self.diagnostic_text) then return end
    local model = self.model or {}
    self:_set_text(self.diagnostic_text, t("ui.debug.summary", {
        status = model.status or t("ui.diagnostics.not_refreshed"),
        paints = #(model.rows or {}),
        coverage = model.stockComplete == true and t("ui.summary.complete") or t("ui.summary.incomplete"),
        recipes = model.recipeCatalogComplete == true and t("ui.summary.complete") or t("ui.summary.incomplete"),
    }))
end

function M:_page(direction)
    if not self:is_connected() or not PAINT_TABS[self.active_tab] then return end
    if not self.active_paint_cache or not self.active_paint_cache.ready then return end
    local offset = math.max(0, self.page_offset + direction * self.page_size)
    if direction > 0 and not self.has_more then return end
    self.page_offset = offset
    self:_queue_render(self.model, true, true)
end

function M:set_progress(progress)
    if progress and self.progress and type(progress.generation) == "number" and type(self.progress.generation) == "number"
        and progress.generation < self.progress.generation then return false end
    self.progress = progress
    if not valid(self.progress_label) then return true end
    local p = progress or {}
    local outcome = p.outcome or p.state
    local active = outcome == nil and p.mode ~= nil and p.mode ~= "idle" or outcome == "running"
    local total, completed = tonumber(p.total), tonumber(p.completed)
    local containers = p.unit == "containers" and completed and completed >= 0 and completed < math.huge
    local determinate = active and p.mode == "determinate" and total and completed
        and (total > 0 or containers and total == 0) and total < math.huge and completed >= 0 and completed <= total
    local labels = { recipes = "ui.progress.recipes", finding = "ui.progress.finding", scan = "ui.progress.scan",
        counting = "ui.progress.scan", applying = "ui.progress.tiles", render = "ui.progress.updating", finalizing = "ui.progress.updating",
        learning = "ui.progress.learning", source_discovery = "ui.progress.finding", scanning = "ui.progress.finding", inventory_capture = "ui.progress.scan",
        paint_cache = "ui.progress.recipes" }
    local label = t(determinate and (p.unit == "tiles" and "ui.progress.tiles" or p.unit == "recipes" and "ui.progress.recipes" or "ui.progress.scan")
        or labels[p.phase] or p.kind == "recipes" and "ui.progress.recipes" or "ui.progress.updating")
    if outcome == "error" or p.coverage == "partial" then label = t("ui.progress.partial")
    elseif outcome == "cancelled" then label = t("ui.status.cancelled")
    elseif outcome == "done" or outcome == "success" then label = t("ui.progress.updated")
    elseif active and containers then
        label = t(determinate and "ui.progress.containers" or "ui.progress.containers_total_unknown",
            { completed = completed, total = total })
    elseif determinate then
        label = t("ui.progress.count", { phase = label, completed = completed, total = total, remaining = total - completed })
    elseif not active then label = "" end
    self.spinner:SetVisibility(active and not determinate and outcome ~= "error" and p.coverage ~= "partial" and 0 or 1)
    local show_bar = determinate and total > 0
    self.progress_bar:SetVisibility(show_bar and 0 or 1)
    if show_bar then self.progress_bar:SetPercent(completed / total) end
    self:_set_text(self.progress_label, label)
    if determinate then
        self:_tooltip(self.progress_label, t("ui.progress.detail", { completed = completed, total = total,
            unit = t(containers and "ui.progress.unit.containers" or p.unit == "tiles" and "ui.progress.unit.tiles"
                or p.unit == "recipes" and "ui.progress.unit.recipes" or "ui.progress.unit.objects"), remaining = total - completed }))
    else
        pcall(function() self.progress_label:SetToolTip(nil) end)
    end
    return true
end

function M:_build()
    self.language_revision = messages.revision
    self.transfer_controls = type(self.callbacks.transfer_paint) == "function" and {} or nil
    -- Retain the newly created host's native canvas: Create may already have
    -- initialized its Slate tree. Only our own panel is attached below it.
    local page = self:_make("VerticalBox")
    self.frame = self:_border(page, C.background, 16)
    local slot = self.root:AddChildToCanvas(self.frame)
    self.frame_slot = slot
    slot:SetAutoSize(false)
    slot:SetPosition({ X = 0, Y = 0 })
    slot:SetSize({ X = 900, Y = 700 })
    slot:SetAlignment({ X = 0.5, Y = 0.5 })
    slot:SetAnchors({ Minimum = { X = 0.5, Y = 0.5 }, Maximum = { X = 0.5, Y = 0.5 } })
    self.frame:SetRenderTransformPivot({ X = 0.5, Y = 0.5 })

    self.icons_shared = false
    if type(self.callbacks.icons) == "function" then
        local ok, icons = pcall(self.callbacks.icons)
        if ok and icons then self.icons, self.icons_shared = icons, true end
    end
    if not self.icons then
        local ok, icons = pcall(require, "paintmanager.ui_icons")
        if ok and type(icons.new) == "function" then
            self.icons = icons.new(self.tree, self.config, function(name) return self:_make(name) end)
            if type(self.icons.host) == "function" then self:_add(page, self.icons:host()) end
            if type(self.icons.preload_all) == "function" then self.icons:preload_all() end
        end
    end
    self.tab_controls = {}
    local function navigation_button(tab, width)
        local button = self:_button(caption(PAGE_KEYS[tab]), function() self:_select_tab(tab, true) end, nil, nil, tab)
        self.tab_controls[tab] = self.buttons[#self.buttons]
        return self:_sized(button, width, 36)
    end
    local title = self:_make("HorizontalBox")
    self:_add(title, self:_label(caption("ui.title"), 24, C.accent), true)
    local settings_button = navigation_button("settings", 155)
    self.debug_tab = navigation_button("debug", 165)
    local refresh = self:_button(caption("ui.button.refresh"), function()
        if self.active_tab == "presets" then
            self:_preset_action("preset_refresh", self.preset_generation, self.preset_shell_generation)
        end
    end, nil, nil, "refresh")
    self.preset_refresh_control = self.buttons[#self.buttons]
    self.preset_refresh_box = self:_sized(refresh, 125, 36)
    self.connection_actions = {
        settings_button,
        self.debug_tab,
        self.preset_refresh_box,
    }
    for _, widget in ipairs(self.connection_actions) do self:_add(title, widget) end
    self.close_button = self:_button(caption("ui.button.close"), function() self:close("user") end, nil, nil, "close")
    -- Close remains first in polling order even when many tile controls exist.
    local close_record = table.remove(self.buttons)
    close_record.connection_close = true
    table.insert(self.buttons, 1, close_record)
    self:_add(title, self:_sized(self.close_button, 100, 36))
    self:_add(page, title)
    local signal = self:_make("VerticalBox")
    local signal_title = self:_label(caption("ui.connection.lost"), 30, C.warning)
    signal_title:SetJustification(1)
    self:_add(signal, signal_title)
    self.connection_description = self:_label(t("ui.connection.unavailable"), 18, C.muted)
    self.connection_description:SetJustification(1)
    self:_add(signal, self.connection_description)
    self.connection_distance = self:_label("", 16, C.muted)
    self.connection_distance:SetJustification(1)
    self:_add(signal, self.connection_distance)
    if self.transfer_controls then
        self.signal_return = self:_transfer_button("return_all", 245, 36, true)
        self:_add(signal, self.signal_return.box):SetHorizontalAlignment(2)
        self.signal_transfer_status = self:_label("", 14, C.accent)
        self:_add(signal, self.signal_transfer_status):SetHorizontalAlignment(2)
    end
    -- Keep the 1774x887 logical reference canvas independent of the approved
    -- 1024x512 pixel texture. ScaleToFit/DownOnly retains the existing 2:1 fit.
    self.connection_illustration = self:_make("Image")
    self.connection_illustration:SetVisibility(1)
    self.connection_illustration:SetClipping(1)
    self.connection_illustration_scale = self:_make("ScaleBox")
    self.connection_illustration_scale:SetStretch(2)
    self.connection_illustration_scale:SetStretchDirection(1)
    local art_slot = self.connection_illustration_scale:AddChild(self:_sized(self.connection_illustration, 1774, 887))
    art_slot:SetHorizontalAlignment(2); art_slot:SetVerticalAlignment(2)
    local art_space = self:_add(signal, self.connection_illustration_scale, true)
    art_space:SetHorizontalAlignment(0); art_space:SetVerticalAlignment(0)
    self.connection_panel = self:_border(signal, C.panel, 32)
    self:_add(page, self.connection_panel, true)
    self.content_panel = self:_make("VerticalBox")
    self:_add(page, self.content_panel, true)
    page = self.content_panel
    local tabs = self:_make("HorizontalBox")
    for _, tab in ipairs({ "learned", "ready", "missing", "presets" }) do
        self:_add(tabs, navigation_button(tab, 165))
    end
    self:_add(page, tabs)
    local tools = self:_make("HorizontalBox")
    self.stock_toolbar = tools
    self.stock_radius_label = self:_label("", 13, C.muted)
    self:_add(tools, self.stock_radius_label, true)
    local learn_all = self:_button(caption("ui.button.learn_all"), function() end, "paint", nil, "learn", caption("ui.view.scope"))
    self.learn_all_control = self.buttons[#self.buttons]
    self.learn_all_control.kind = "learn_all"
    learn_all:SetIsEnabled(false)
    self:_add(tools, self:_sized(learn_all, 155, 32))
    self:_add(page, tools)
    local activity = self:_make("HorizontalBox")
    self.spinner = self:_make("CircularThrobber")
    self.spinner:SetPeriod(0.8); self.spinner:SetRadius(8); self.spinner:SetNumberOfPieces(8)
    self.progress_bar = self:_make("ProgressBar")
    self.progress_bar:SetIsMarquee(false)
    self:_add(activity, self:_sized(self.spinner, 20, 20))
    self:_add(activity, self:_sized(self.progress_bar, 95, 4))
    self.progress_label = self:_label("", 13, C.muted)
    self:_add(activity, self.progress_label, true)
    self:_add(page, self:_sized(activity, nil, 24))
    self.switcher = self:_make("WidgetSwitcher")
    self:_add(page, self.switcher, true)
    local paints_page = self:_make("VerticalBox")
    local search_bar = self:_make("HorizontalBox")
    self.search_box = self:_entry("ui.search.hint")
    self.search_box:SetText(FText(self.view.query)); self.last_search_text = self.view.query
    self:_add(search_bar, self:_sized(self.search_box, nil, 34), true)
    self:_add(search_bar, self:_sized(self:_button(caption("ui.search.clear"), function() self:set_view({ query = "" }) end, "paint", nil, "clear"), 90, 34))
    self:_add(search_bar, self:_sized(self:_button("", function() self:_cycle_sort() end, "paint", nil, "sort"), 215, 34))
    self.sort_control = self.buttons[#self.buttons]
    self:_add(paints_page, search_bar)
    local summary_row = self:_make("HorizontalBox")
    self.view_summary = self:_label(t("ui.view.initial"), 13, C.muted)
    self.stock_total_label = self:_label("", 14, C.text)
    self:_add(summary_row, self.view_summary, true)
    self:_add(summary_row, self.stock_total_label)
    self:_add(paints_page, summary_row)
    self:_sync_stock_total(self.model)
    self.paint_views = self:_make("WidgetSwitcher")
    self.paint_caches = {}
    for _, tab in ipairs({ "learned", "ready", "missing" }) do self:_new_paint_cache(tab) end
    local saved = self.reopen_view
    self.reopen_view = nil
    if saved and saved.model == self.model and saved.query == self.view.query and saved.sort == self.view.sort then
        for tab, page in pairs(saved.pages) do
            local cache = self.paint_caches[tab]
            cache.selected, cache.offset, cache.restore_scroll = page.selected, page.offset, page.scroll
        end
    else saved = nil end
    -- A new native switcher starts at child zero even when the remembered
    -- Lua tab and its cached page are already Can Learn or Need Cans.
    self.active_paint_cache = self.paint_caches[PAINT_TABS[self.active_tab] and self.active_tab or "learned"]
    self.paint_views:SetActiveWidgetIndex(self.active_paint_cache.index)
    self:_use_paint_cache(self.active_paint_cache)
    self:_add(paints_page, self.paint_views, true)
    local paging = self:_make("HorizontalBox")
    self:_add(paging, self:_sized(self:_button(caption("ui.page.previous"), function() self:_page(-1) end, "paint", nil, "back"), 110, 30))
    self.previous_control = self.buttons[#self.buttons]
    self:_add(paging, self:_sized(self:_button(caption("ui.page.next"), function() self:_page(1) end, "paint"), 110, 30))
    self.next_control = self.buttons[#self.buttons]
    if self.transfer_controls then
        for _, command in ipairs({ "gather_all", "return_all" }) do
            local control = self:_transfer_button(command, 195, 32)
            self:_add(paging, control.box)
        end
    end
    self:_add(paints_page, paging)
    self.details = self:_make("HorizontalBox")
    self:_build_details()
    local details_border = self:_border(self.details, C.paint_details, PAINT_DETAIL_PADDING)
    self:_add(paints_page, self:_sized(details_border, nil, PAINT_DETAIL_SIZE + 2 * PAINT_DETAIL_PADDING))
    self.switcher:AddChild(self:_border(paints_page))
    self.settings_page = self:_make("VerticalBox")
    local settings_scroll = self:_make("ScrollBox")
    settings_scroll:AddChild(self.settings_page)
    self.switcher:AddChild(self:_border(settings_scroll))
    self.debug_page = self:_make("VerticalBox")
    self.switcher:AddChild(self:_border(self.debug_page))
    self.presets_host = self:_border(self:_make("VerticalBox"))
    self.switcher:AddChild(self.presets_host)
    self:_build_settings()
    self.status_label = self:_label("", 13, C.accent)
    self:_add(page, self.status_label)
    if self.transfer_controls then
        self.transfer_result_label = self:_label("", 13, C.accent)
        self:_add(page, self.transfer_result_label)
    end
    self:_select_tab(self.active_tab)
    if saved and saved.projection and saved.projection.favorite_revision == (self.favorite_order_revision or 0) then
        self.paint_projection = saved.projection
        self:_queue_render(self.model, false, true)
    else
        self:set_model(self.model)
        if saved then
            for tab, page in pairs(saved.pages) do self.paint_caches[tab].offset = page.offset end
        end
    end
    self:set_progress(self.progress)
    self:_render_status()
    self:set_connection(self.connection)
end

local CACHE_FIELDS = { "paint_list", "checking_list", "paint_grid_box", "checking_grid_box", "checking_button", "checking_control", "visible_tiles", "visible_tiles_by_id" }

function M:_new_paint_cache(tab)
    local cache = { tab = tab, offset = 0,
        visible_tiles = {}, visible_tiles_by_id = {}, selected = nil }
    -- Native widgets stay attached below this retained switcher, including
    -- hidden pages. Lua references and Outer alone do not establish ownership.
    cache.index = ({ learned = 0, ready = 1, missing = 2 })[tab]
    cache.scroll = self:_make("ScrollBox")
    cache.scroll:SetVisibility(2) -- Hidden preserves layout while the page is built.
    local grids = self:_make("VerticalBox"); cache.scroll:AddChild(grids)
    cache.paint_list = self:_make("UniformGridPanel")
    cache.paint_grid_box = self:_sized(cache.paint_list, 116)
    self:_add(grids, cache.paint_grid_box):SetHorizontalAlignment(1)
    cache.checking_button = self:_button(t("ui.checking.caption", { count = 0 }), function()
        if self.active_paint_cache ~= cache or not cache.ready then return end
        self.checking_expanded = not self.checking_expanded
        self:_queue_render(self.model, true, true)
    end, "paint")
    cache.checking_control = self.buttons[#self.buttons]
    cache.checking_control.paint_cache = cache
    self:_add(grids, cache.checking_button)
    cache.checking_list = self:_make("UniformGridPanel")
    cache.checking_grid_box = self:_sized(cache.checking_list, 116)
    self:_add(grids, cache.checking_grid_box):SetHorizontalAlignment(1)
    self.paint_views:AddChild(cache.scroll)
    self.paint_caches[tab] = cache
end

function M:_conceal_paint_cache(cache)
    cache.ready = false
    cache.scroll:SetVisibility(2) -- ESlateVisibility.Hidden in the reference JMAP.
    if cache == self.active_paint_cache then
        if self.previous_control then self.previous_control.widget:SetIsEnabled(false) end
        if self.next_control then self.next_control.widget:SetIsEnabled(false) end
    end
end

function M:_paint_cache_current(cache, generation, model)
    return self.open and self.render_generation == generation and self.model == model
        and self.paint_caches and self.paint_caches[cache.tab] == cache
end

function M:_use_paint_cache(cache)
    for _, name in ipairs(CACHE_FIELDS) do self[name] = cache[name] end
    self.page_offset, self.selected_paint_id = cache.offset or 0, cache.selected
end

function M:_save_paint_cache(cache)
    for _, name in ipairs(CACHE_FIELDS) do cache[name] = self[name] end
    cache.offset, cache.selected, cache.checking_expanded = self.page_offset, self.selected_paint_id, self.checking_expanded == true
end

function M:_bind_cached_controls(cache)
    self:_clear_learn_buttons()
    if not cache.ready and (not cache.job or cache.job.phase == "clear") then return end
    local generation = self.render_generation
    for _, entry in ipairs(cache.visible_tiles) do
        entry.generation = generation
        local select, favorite = entry.select_control, entry.favorite_control
        select.generation, favorite.generation = generation, generation
        select.release_required, favorite.release_required = select.release_required or select.pressed, favorite.release_required or favorite.pressed
        select.pressed, favorite.pressed = false, false
        select.action = function() if self.active_paint_cache == cache then self:_select_paint(entry.row.id, generation) end end
        favorite.action = function() if self.active_paint_cache == cache then self:_toggle_favorite(entry.row, generation) end end
        self.buttons[#self.buttons + 1] = select
        self.buttons[#self.buttons + 1] = favorite
    end
    self:_sync_favorite_controls()
end

local function update_tab_count(self, tab, control, counts)
    local count = counts[tab] or 0
    if control.display_count == count then return end
    control.display_count = count
    self:_set_text(control.label, t("ui.tab.count", { name = t(PAGE_KEYS[tab]), count = count }))
end

function M:_show_cached_summary(cache)
    local result = cache.result
    if not result then return end
    self.category_counts, self.has_more = result.category_counts, result.has_more
    self.previous_control.widget:SetIsEnabled(self.page_offset > 0)
    self.next_control.widget:SetIsEnabled(self.has_more)
    local summary = t("ui.page.summary", { shown = result.visible_count,
        total = result.base_visible_count, page = math.floor(self.page_offset / self.page_size) + 1 })
    if summary ~= self.last_page_summary then
        self.last_page_summary = summary
        self:_set_text(self.view_summary, summary)
    end
    for tab, record in pairs(self.tab_controls) do
        if PAINT_TABS[tab] then update_tab_count(self, tab, record, result.category_counts) end
    end
    self:_set_learn_all_ready(self.model, self.render_generation, result.ready_count)
    local selected = cache.visible_tiles_by_id[self.selected_paint_id]
    self:_render_details(selected and selected.row or cache.visible_tiles[1] and cache.visible_tiles[1].row,
        self.model, self.model and "ui.empty.no_matches" or "ui.empty.not_refreshed")
end

function M:refresh_language()
    if not self.open or self.language_revision == messages.revision then return end
    self.language_revision = messages.revision
    self:_refresh_language_widgets()
    self:_sync_view_controls()
    for tab, control in pairs(self.tab_controls or {}) do
        control.display_count = nil
        if PAINT_TABS[tab] and self.category_counts then update_tab_count(self, tab, control, self.category_counts) end
    end
    for _, record in ipairs(self.transfer_controls or {}) do
        local label, help = transfer_caption(record.transfer, record.quantity)
        self:_set_text(record.label, label)
        self:_set_text(record.tooltip_label, record.unavailable or help)
        record.help = help
    end
    self:_sync_transfer_controls()
    self:set_connection(self.connection)
    self:set_progress(self.progress)
    self:_render_status()
    if self.render_persistence then self:set_persistence(self.render_persistence(), self.render_persistence) end
    -- Reuse the plain projection and the same native host. Rebuild only
    -- presentation rows through the ordinary bounded renderer.
    for _, cache in pairs(self.paint_caches or {}) do
        self:_conceal_paint_cache(cache)
        cache.job, cache.result, cache.patch_existing = nil, nil, nil
    end
    self:_queue_render(self.model, true, true)
    if self.preset_list then self:_queue_preset_render() end
end

function M:_activate_paint_tab(tab)
    local previous = self.active_paint_cache
    if previous then self:_save_paint_cache(previous) end
    local cache = self.paint_caches and self.paint_caches[tab]
    if not cache then return end
    if not processing.get("tab_cache_enabled", true) then self:_conceal_paint_cache(cache); cache.job, cache.result = nil, nil end
    if cache.ready and cache.checking_expanded ~= (self.checking_expanded == true) and tab == "missing" then self:_conceal_paint_cache(cache); cache.job = nil end
    if cache.membership_revision ~= (self.membership_revision or 0) then self:_conceal_paint_cache(cache); cache.job = nil end
    self.render_generation = (self.render_generation or 0) + 1
    self.active_paint_cache = cache
    self:_use_paint_cache(cache)
    self.paint_views:SetActiveWidgetIndex(cache.index)
    if not processing.get("view_cache_enabled", true) then
        self:_queue_render(self.model, true)
        return
    end
    if self.paint_projection and (self.paint_projection.favorite_revision ~= (self.favorite_order_revision or 0)
        or self.paint_projection.stock_order_dirty) then
        self:_queue_render(self.model, true)
        return
    end
    self:_refresh_membership_partition()
    self:_bind_cached_controls(cache)
    if cache.ready then
        local generation, model = self.render_generation, self.model
        self.render_job = nil
        self:_show_cached_summary(cache)
        if self:_paint_cache_current(cache, generation, model) and cache.ready then
            cache.scroll:SetVisibility(0)
            self:_paint_page_shown(cache, true)
        end
    else
        if not self.paint_projection and not self.projection_job then
            self.projection_favorite_revision = self.favorite_order_revision or 0
            self.projection_job = paint_view.begin(self.model, { query = self.view.query, filter = "all", sort = self.view.sort,
                favorites = self.favorites, include_groups = false, full_catalog = true,
                max_catalog = self.config.max_catalog or 512, generation = self.render_generation })
        end
        self.render_job = cache.job or self:_new_render_job(cache)
        cache.job = self.render_job
        self.render_job.background = false
        self.render_job.generation = self.render_generation
        self:_set_learn_all_ready(self.model, self.render_generation, 0)
    end
end

function M:_new_render_job(cache)
    local patch = cache.patch_existing
    cache.patch_existing = nil
    if not patch then self:_conceal_paint_cache(cache) end
    cache.membership_revision = self.membership_revision or 0
    return { generation = self.render_generation, model = self.model, cache = cache,
        patch = patch, phase = patch and "prepare" or "clear", completed = 0, total = #(self.model and self.model.rows or {}) * 16 + 20,
        paint_index = 1, checking_index = 1, paint_done = 0, ready_count = 0 }
end

function M:_prewarm_paint_tab()
    if self.model and self.model.learnedOnly or self.waiting_stock and self.active_tab == "learned"
        or not processing.get("automatic_preparation", true) or not processing.get("prewarm_tabs", true)
        or not processing.get("tab_cache_enabled", true) then return end
    if self.render_job or not self.paint_projection or not self.open or not PAINT_TABS[self.active_tab] then return end
    self:_refresh_membership_partition()
    for _, tab in ipairs({ "learned", "ready", "missing" }) do
        local cache = self.paint_caches[tab]
        if cache ~= self.active_paint_cache and cache.membership_revision ~= (self.membership_revision or 0) then self:_conceal_paint_cache(cache); cache.job = nil end
        if not cache.ready then
            self.render_job = cache.job or self:_new_render_job(cache)
            cache.job, self.render_job.background, self.render_job.generation = self.render_job, true, self.render_generation
            return
        end
    end
end

function M:_refresh_membership_partition()
    local projection = self.paint_projection
    if not projection or not projection.membership_dirty then return end
    projection.sorted, projection.index = projection.all_rows, 1
    projection.pages = { learned = {}, ready = {}, missing = {}, checking = {} }
    projection.membership_dirty = nil
end

function M:_fit()
    local size = self.layout:GetViewportSize(self.pc)
    local dpi = self.layout:GetViewportScale(self.pc)
    local fit = M.fit_geometry(size.X, size.Y, dpi)
    local key = tostring(size.X) .. ":" .. tostring(size.Y) .. ":" .. tostring(dpi) .. ":" .. self.preferences.tileDensity
    if key == self.geometry_key then return end
    local columns = M.grid_columns(fit.layoutWidth, self.preferences.tileDensity)
    local reflow = self.grid_column_count ~= nil and columns ~= self.grid_column_count
    self.frame_slot:SetSize({ X = fit.layoutWidth, Y = fit.layoutHeight })
    self.frame:SetRenderScale({ X = fit.scale, Y = fit.scale })
    if self.panel_width ~= fit.layoutWidth then
        -- Slate checkboxes auto-size their content. Bound its desired width so
        -- even a caption longer than the window wraps inside the clickable area.
        for _, checkbox in pairs(self.checkboxes) do
            checkbox.caption_box:SetMaxDesiredWidth(fit.layoutWidth - SETTINGS_CHECKBOX_GUTTER)
        end
    end
    -- Translate one third of the viewport into the panel's unscaled layout units.
    self.preset_action_width = math.ceil(fit.logicalWidth / (3 * fit.scale))
    self.detail_learn_box:SetWidthOverride(self.preset_action_width)
    if self.detail_actions_box then self.detail_actions_box:SetWidthOverride(self.preset_action_width) end
    if valid(self.preset_apply_box) then self.preset_apply_box:SetWidthOverride(self.preset_action_width) end
    self.panel_width, self.panel_height, self.grid_column_count = fit.layoutWidth, fit.layoutHeight, columns
    self.icon_physical_scale = dpi * fit.scale
    if self.icons and type(self.icons.set_scale) == "function" then self.icons:set_scale(self.icon_physical_scale) end
    self.geometry_key = key
    if reflow then self:_queue_render(self.model, true) end
    if self.callbacks.log then
        pcall(function()
            self.callbacks.log(t("ui.log.layout", { root = self.root:GetFullName(), class = self.root:GetClass():GetFullName(),
                width = string.format("%.0f", size.X), height = string.format("%.0f", size.Y), dpi = string.format("%.3f", dpi),
                scale = string.format("%.4f", fit.scale), left = string.format("%.1f", fit.left), top = string.format("%.1f", fit.top),
                panelWidth = string.format("%.1f", fit.width), panelHeight = string.format("%.1f", fit.height) }))
        end)
    end
end

local function absent_opacity(config)
    local opacity = tonumber(config.ui_absent_opacity) or 0.4
    if opacity ~= opacity or opacity <= 0 or opacity >= 1 then return 0.4 end
    return opacity
end

function M:_paint_texture(icon_path)
    if not icon_path then return nil end
    local ok, texture = pcall(function()
        local candidate = StaticFindObject(path_only(icon_path))
        if valid(candidate) and candidate:IsA("/Script/Engine.Texture2D") then return candidate end
    end)
    if ok then return texture end
end

function M:_icon(row, absent, size)
    local image, texture
    local candidate = self:_paint_texture(row.iconPath)
    if candidate then
        local ok = pcall(function()
            image = self:_make("Image")
            image:SetBrushFromTexture(candidate, false)
            if absent then
                -- Slate's native disabled image treatment is the selected
                -- desaturation candidate; real visual qualification is pending.
                image:SetIsEnabled(false)
                image:SetRenderOpacity(absent_opacity(self.config))
            end
            texture = candidate
        end)
        if not ok then image = nil end
    end
    local content = image or self:_border(self:_label(t("ui.value.unknown"), 26, C.muted))
    if absent and not image then content:SetRenderOpacity(absent_opacity(self.config)) end
    return self:_sized(content, size or 74, size or 74), image, content, texture
end

local measured_stock = paint_view.stock_measured

local function stock_caption(model, row)
    local count = paint_view.physical_count(model, row)
    if measured_stock(model, row) then return tostring(count) end
    if model.learnedOnly or model.cachePreview or not paint_view.stock_current(model, row) then
        count = type(model.backpackCounts) == "table" and model.backpackCounts[row.id] or nil
    end
    if count and count > 0 then return t("ui.tile.lower_bound", { count = count }) end
    return t("ui.value.unknown")
end

local function paint_tooltip(row, caption, absent)
    local recipe = t(row.recipeState == "unlocked" and "ui.recipe.unlocked" or row.recipeState == "locked" and "ui.recipe.locked" or "ui.recipe.unknown")
    return t("ui.tile.tooltip", { name = row.displayName or t("ui.paint.name_unavailable"), recipe = recipe,
        stock = absent and t("ui.tile.absent") or t("ui.tile.stock", { count = caption }) })
end

local function place_cell(grid, cell, position, columns)
    local slot = grid:AddChildToUniformGrid(cell, math.floor((position - 1) / columns), (position - 1) % columns)
    slot:SetHorizontalAlignment(1)
    slot:SetVerticalAlignment(1)
end

function M:_render_paint_row(row, _, model, index, grid)
    local size = self.preferences.tileDensity == "compact" and 96 or 108
    local columns = M.grid_columns(self.panel_width or 900, self.preferences.tileDensity)
    local tile, generation = self:_make("CanvasPanel"), self.render_generation
    local sized = self:_sized(self:_border(tile, C.background, 4), size + 8, size + 8)
    grid = grid or self.paint_list
    local position = index or (#self.visible_tiles + 1)
    -- Preserve the square desired size when the grid distributes spare width.
    place_cell(grid, sized, position, columns)
    tile:SetClipping(1)
    local absent = measured_stock(model, row) and paint_view.physical_count(model, row) == 0
    local name = row.displayName or t("ui.paint.name_unavailable")
    local body = self:_make("Button")
    local body_slot = tile:AddChildToCanvas(body)
    body_slot:SetPosition({ X = 0, Y = 0 }); body_slot:SetSize({ X = size, Y = size })
    body:SetBackgroundColor(row.id == self.selected_paint_id and C.selected or C.button)
    local image, decorative, decoration, texture = self:_icon(row, absent, size - 28)
    body:SetContent(image)
    local function overlay(widget, x, y, width, height)
        local slot = tile:AddChildToCanvas(widget)
        slot:SetPosition({ X = x, Y = y }); slot:SetSize({ X = width, Y = height })
    end
    local label
    if self.preferences.showNames then
        label = self:_label(name, 12)
        label:SetVisibility(4)
        overlay(label, 5, size - 21, size - 10, 18)
    end
    local owner_cache = self.building_paint_cache or self.active_paint_cache
    self.buttons[#self.buttons + 1] = { widget = body, label = label, action = function()
        if self.active_paint_cache == owner_cache then self:_select_paint(row.id, generation) end
    end, scope = "paint", kind = "paint_select", generation = generation, pressed = false }
    local caption = stock_caption(model, row)
    local count = self:_label(caption, 16, C.text)
    count:SetVisibility(4)
    local badge = self:_border(count, C.background, 2)
    badge:SetVisibility(4)
    overlay(badge, size - 45, size - 48, 42, 25)
    local key = favorite_key(row)
    local favorite = key and self.favorites[key] == true
    local star = self:_button(t(favorite and "ui.favorite.filled" or "ui.favorite.empty"), function()
        if self.active_paint_cache == owner_cache then self:_toggle_favorite(row, generation) end
    end, "paint", nil, favorite and "star_filled" or "star", t(favorite and "ui.favorite.remove" or "ui.favorite.add"))
    local favorite_button = self.buttons[#self.buttons]
    favorite_button.kind, favorite_button.generation, favorite_button.favorite_key = "favorite", generation, key
    star:SetIsEnabled(key ~= nil and type(self.callbacks.favorite) == "function")
    overlay(star, size - 35, 3, 32, 32)
    local mark = paint_view.classify(model, row)
    local description = paint_tooltip(row, caption, absent)
    local entry = { row = row, widget = body, image = decorative, decoration = decoration, texture = texture,
        absent = absent, count = count, star = star, cell = sized, grid = grid, position = position,
        caption = caption, description = description,
        generation = generation, tooltip_label = self:_tooltip(body, description), mark = mark }
    entry.select_control = self.buttons[#self.buttons - 1]
    entry.favorite_control = favorite_button
    entry.select_control.paint_cache, favorite_button.paint_cache = self.building_paint_cache or self.active_paint_cache, self.building_paint_cache or self.active_paint_cache
    self.visible_tiles[#self.visible_tiles + 1] = entry
    if row.id ~= nil then self.visible_tiles_by_id[row.id] = entry end
end

function M:_build_details()
    local column_padding = { Left = 4, Top = 0, Right = 4, Bottom = 0 }
    local preview = self:_make("Overlay")
    self.detail_image = self:_make("Image")
    self.detail_fallback = self:_label(t("ui.value.unknown"), 26, C.muted)
    local image_slot = preview:AddChild(self.detail_image)
    image_slot:SetHorizontalAlignment(0); image_slot:SetVerticalAlignment(0)
    image_slot:SetPadding(margin(0))
    local fallback_slot = preview:AddChild(self.detail_fallback)
    fallback_slot:SetHorizontalAlignment(2); fallback_slot:SetVerticalAlignment(2)
    self.detail_preview = self:_sized(preview, PAINT_DETAIL_SIZE, PAINT_DETAIL_SIZE)
    preview.Slot:SetHorizontalAlignment(0); preview.Slot:SetVerticalAlignment(0)
    self.detail_preview:SetVisibility(1)
    local preview_slot = self.details:AddChild(self.detail_preview)
    preview_slot:SetVerticalAlignment(0)
    preview_slot:SetPadding(column_padding)

    local metadata = self:_make("VerticalBox")
    self.detail_title = self:_label(t("ui.paint.select"), 18)
    self.detail_description = self:_label("", 14, C.muted)
    self:_add(metadata, self.detail_title)
    self:_add(metadata, self.detail_description)
    if self.transfer_controls then
        self.detail_backpack = self:_label("", 14, C.muted)
        metadata:AddChild(self.detail_backpack):SetPadding({ Left = 4, Top = 0, Right = 4, Bottom = 0 })
    end
    self:_add(self.details, metadata, true):SetVerticalAlignment(2)

    local button = self:_button(caption("ui.button.learn_recipe"), function() end,
        "paint", C.selected, "learn", caption("ui.learn.help"), 56)
    self.detail_learn_control = self.buttons[#self.buttons]
    self.detail_learn_control.kind = "paint_detail"
    button:SetIsEnabled(false)
    self.detail_learn_box = self:_sized(button)
    button.Slot:SetHorizontalAlignment(0); button.Slot:SetVerticalAlignment(0)
    self.detail_learn_box:SetVisibility(1)
    local action_box = self.detail_learn_box
    if self.transfer_controls then
        local actions = self:_make("VerticalBox")
        local learn = actions:AddChild(self.detail_learn_box)
        learn:SetSize({Value = 1, SizeRule = 1})
        learn:SetVerticalAlignment(0)
        -- Both directions can be available below the backpack target. Keep
        -- them on one row so the Learn icon retains its height.
        local transfers = self:_make("HorizontalBox")
        for _, command in ipairs({ "gather_paint", "return_paint" }) do
            local control = self:_transfer_button(command, nil, 34)
            transfers:AddChild(control.box):SetSize({ Value = 1, SizeRule = 1 })
        end
        actions:AddChild(transfers):SetHorizontalAlignment(0)
        self.detail_actions_box = self:_sized(actions)
        action_box = self.detail_actions_box
    end
    local learn_slot = self.details:AddChild(action_box)
    learn_slot:SetVerticalAlignment(0)
    learn_slot:SetPadding(column_padding)
end

function M:_render_details(row, model, empty_key)
    local previous = self.visible_tiles_by_id and self.visible_tiles_by_id[self.selected_paint_id]
    if row and previous and previous.row.id ~= row.id and valid(previous.widget) then previous.widget:SetBackgroundColor(C.button) end
    self.detail_row = row
    local selected = row and self.visible_tiles_by_id and self.visible_tiles_by_id[row.id]
    if row then
        self.selected_paint_id = row.id
        if selected and valid(selected.widget) then selected.widget:SetBackgroundColor(C.selected) end
    end
    self:_set_text(self.detail_title, row and (row.displayName or t("ui.paint.name_unavailable")) or t(empty_key or "ui.paint.select"))
    self:_sync_transfer_controls()
    local record = self.detail_learn_control
    if not row then
        self.detail_preview:SetVisibility(1)
        self:_set_text(self.detail_description, "")
        record.kind, record.row = "paint_detail", nil
        record.widget:SetIsEnabled(false)
        self.detail_learn_box:SetVisibility(1)
        return
    end
    local recipe = t(row.recipeState == "unlocked" and "ui.recipe.unlocked" or row.recipeState == "locked" and "ui.recipe.locked" or "ui.recipe.unknown")
    local absent = measured_stock(model, row) and paint_view.physical_count(model, row) == 0
    local stock = absent and t("ui.tile.absent") or t("ui.tile.stock", { count = stock_caption(model, row) })
    local texture = selected and selected.row == row and selected.texture
    local has_image = valid(texture) and pcall(function() self.detail_image:SetBrushFromTexture(texture, false) end)
    self.detail_image:SetVisibility(has_image and 4 or 1)
    self.detail_image:SetIsEnabled(not absent)
    self.detail_fallback:SetVisibility(has_image and 1 or 4)
    self.detail_preview:SetRenderOpacity(absent and absent_opacity(self.config) or 1)
    self.detail_preview:SetVisibility(4)
    self:_set_text(self.detail_description, t("ui.paint.details", { recipe = recipe, stock = stock }))
    local eligible = self:is_connected() and not self:_paint_actions_pending() and learn_eligible(model, row)
    record.kind, record.row = eligible and "learn_recipe" or "paint_detail", row
    self.detail_learn_box:SetVisibility(eligible and 0 or 1)
    record.widget:SetIsEnabled(eligible and not self.learning)
    if eligible then
        local generation, id = self.render_generation, row.id
        record.generation = generation
        record.action = function()
            if self.detail_row == row and record.row == row and record.kind == "learn_recipe"
                and learn_eligible(self.model, row) then self:_request_learning(id, generation) end
        end
    end
end

-- A successful synchronous Learn changes one existing row. Keep the current
-- order/page until a normal refresh; only its native presentation is patched.
function M:update_recipe(item_id)
    if not self.open or not self.model then return end
    local entry = self.visible_tiles_by_id and self.visible_tiles_by_id[item_id]
    if entry and entry.generation == self.render_generation then
        local row = entry.row
        entry.description = paint_tooltip(row, stock_caption(self.model, row), entry.absent)
        self:_set_text(entry.tooltip_label, entry.description)
        local mark = paint_view.classify(self.model, row)
        if mark ~= entry.mark then
            if entry.mark == "ready" then self.learn_all_ready_count = math.max(0, (self.learn_all_ready_count or 0) - 1) end
            if entry.mark == "ready" and mark == "learned" then
                self.membership_revision = (self.membership_revision or 0) + 1
                if self.paint_projection then
                    self.paint_projection.membership_dirty = true
                    self.paint_projection.ready_count = math.max(0, (self.paint_projection.ready_count or 0) - 1)
                end
                if self.render_job and self.render_job.background then
                    self.render_job.membership_stale = true
                end
                local seen = {}
                for _, counts in pairs({ self.category_counts, self.render_job and self.render_job.category_counts }) do
                    if not seen[counts] then
                        counts.ready, counts.learned = math.max(0, (counts.ready or 0) - 1), (counts.learned or 0) + 1
                        seen[counts] = true
                    end
                end
                if self.render_job then self.render_job.ready_count = math.max(0, (self.render_job.ready_count or 0) - 1) end
                for _, tab in ipairs({ "learned", "ready" }) do
                    local control = self.tab_controls and self.tab_controls[tab]
                    if control and self.category_counts then update_tab_count(self, tab, control, self.category_counts) end
                end
            end
            entry.mark = mark
        end
        if self.detail_row == row then self:_render_details(row, self.model) end
    end
    self:_sync_learn_all_enabled()
end

-- Compare only the bounded, currently mounted page (at most 128 + 128
-- checking tiles). Unchanged cells keep their Slate widget and native slot.
function M:_prepare_page_patch(job)
    job.old_tiles, job.keep = self.visible_tiles, {}
    local old_by_key = {}
    for _, entry in ipairs(job.old_tiles) do old_by_key[paint_view.capture_key(entry.row)] = entry end
    local structural = false
    local function match(rows, grid)
        for index, row in ipairs(rows) do
            local key = paint_view.capture_key(row)
            local entry = old_by_key[key]
            if entry and self.selected_paint_id == entry.row.id then self.selected_paint_id = row.id end
            if entry and entry.row.iconPath == row.iconPath and favorite_key(entry.row) == favorite_key(row) then
                job.keep[key] = entry
                structural = structural or entry.grid ~= grid or entry.position ~= index
            else structural = true end
        end
    end
    match(job.rows, self.paint_list)
    local checking = self.checking_expanded and job.checking_rows or {}
    match(checking, self.checking_list)
    structural = structural or #job.old_tiles ~= #job.rows + #checking
    if structural then self:_conceal_paint_cache(job.cache) end
    self.visible_tiles, self.visible_tiles_by_id = {}, {}
    job.remove_index = 1
    job.phase = structural and "remove" or "paints"
end

function M:_place_capture_row(job, row, index, grid)
    local entry = job.keep and job.keep[paint_view.capture_key(row)]
    if not entry then
        self:_render_paint_row(row, job.model and job.model.stockComplete, job.model or {}, index, grid)
        return
    end
    if entry.grid ~= grid or entry.position ~= index then
        local columns = M.grid_columns(self.panel_width or 900, self.preferences.tileDensity)
        entry.cell:RemoveFromParent()
        place_cell(grid, entry.cell, index, columns)
        entry.grid, entry.position = grid, index
    end
    if entry.row.displayName ~= row.displayName then
        self:_set_text(entry.select_control.label, row.displayName or t("ui.paint.name_unavailable"))
    end
    entry.row = row
    self:_patch_stock_entry(entry, job)
    if not self:_paint_cache_current(job.cache, job.generation, job.model) or self.render_job ~= job then return end
    self.visible_tiles[#self.visible_tiles + 1] = entry
    if row.id then self.visible_tiles_by_id[row.id] = entry end
end

-- Each call performs one bounded preparation item, heading, row or finalization.
-- A native widget call / complete row is atomic: this is a cooperative budget,
-- not a hard deadline capable of interrupting an engine call.
function M:_advance_render(job, budget)
    local model = job.model or {}
    if job.phase == "clear" then
        self:_conceal_paint_cache(job.cache)
        self.paint_list:ClearChildren(); self.checking_list:ClearChildren()
        self.paint_grid_box:SetWidthOverride(1); self.checking_grid_box:SetWidthOverride(1)
        self.visible_tiles, self.visible_tiles_by_id = {}, {}
        if not job.background then self:_render_details(nil, model) end
        self.checking_button:SetVisibility(1)
        if not job.background then
            self.last_page_summary = nil
            self:_set_text(self.view_summary, t("ui.render.building"))
        end
        self:_set_text(self.stock_radius_label, self:_stock_radius_caption(model))
        job.phase = "prepare"
        return
    elseif job.phase == "prepare" then
        if not self.paint_projection then
            local projection = assert(self.projection_job, "Paint projection unavailable")
            local progress = projection:step_one(budget)
            job.worker_defer = progress.defer == true
            if progress.state == "done" then
                local result = progress.result
                self.paint_projection = { sorted = result.rows or {}, all_rows = result.rows or {}, category_counts = result.category_counts or {},
                    favorite_revision = self.projection_favorite_revision or 0,
                    ready_count = result.ready_count or 0, pages = { learned = {}, ready = {}, missing = {}, checking = {} }, index = 1 }
                self.projection_job = nil
            elseif progress.state ~= "running" then error(progress.error or progress.reason or "Paint view preparation stopped") end
            return
        end
        local projection = self.paint_projection
        if projection.sorted then
            local progress = plain_work.run(function()
                local row = projection.sorted[projection.index]
                if not row then return { state = "done" } end
                local category = paint_view.classify(job.model, row)
                local page = projection.pages[category]
                page[#page + 1] = row
                projection.index = projection.index + 1
                return { state = projection.index > #projection.sorted and "done" or "running" }
            end, budget, { group = "projection_primitives" })
            if not progress or progress.state ~= "done" then return end
        end
        projection.sorted = nil
        local rows, checking = projection.pages[job.cache.tab], projection.pages.checking
        if job.patch then
            local total = math.max(#rows, job.cache.tab == "missing" and #checking or 0)
            self.page_offset = math.min(self.page_offset, math.floor(math.max(0, total - 1) / self.page_size) * self.page_size)
        end
        local function slice(source)
            local result = {}
            for index = self.page_offset + 1, math.min(#source, self.page_offset + self.page_size) do result[#result + 1] = source[index] end
            return result
        end
        job.rows, job.checking_rows = slice(rows), job.cache.tab == "missing" and slice(checking) or {}
        job.membership_revision = self.membership_revision or 0
        job.visible_count, job.base_visible_count = #job.rows, #rows
        job.ready_count, job.category_counts = projection.ready_count, projection.category_counts
        job.has_more = math.max(#rows, job.cache.tab == "missing" and #checking or 0) > self.page_offset + self.page_size
        job.checking_count, job.phase = #checking, "paints"
        if job.patch then
            self:_prepare_page_patch(job)
            if job.cache.tab ~= "missing" or #checking == 0 then self.checking_button:SetVisibility(1) end
        end
        local cell = (self.preferences.tileDensity == "compact" and 96 or 108) + 8
        local columns = M.grid_columns(self.panel_width or 900, self.preferences.tileDensity)
        self.paint_grid_box:SetWidthOverride(math.max(1, math.min(#job.rows, columns) * cell))
        self.checking_grid_box:SetWidthOverride(math.max(1, math.min(self.checking_expanded and #job.checking_rows or 0, columns) * cell))
        return
    elseif job.phase == "remove" then
        local old = job.old_tiles[job.remove_index]
        if old then
            if job.keep[paint_view.capture_key(old.row)] ~= old then old.cell:RemoveFromParent() end
            job.remove_index = job.remove_index + 1
        else job.phase = "paints" end
    elseif job.phase == "paints" then
        local row = job.rows[job.paint_index]
        if row then
            self:_place_capture_row(job, row, job.paint_index, self.paint_list)
            if not job.detail_row or row.id == self.selected_paint_id then job.detail_row = row end
            job.paint_index, job.paint_done = job.paint_index + 1, job.paint_done + 1
            return
        end
        if #job.rows == 0 and not job.empty then
            if not job.background then self:_render_details(nil, model, self.model and "ui.empty.no_matches" or "ui.empty.not_refreshed") end
            job.empty = true
            return
        end
        job.phase = "checking"
    elseif job.phase == "checking" then
        if job.cache.tab == "missing" and job.checking_count > 0 then
            self.checking_button:SetVisibility(0)
            self:_set_text(self.checking_control.label, t("ui.checking.caption", { count = job.checking_count }))
            if self.checking_expanded then
                local row = job.checking_rows[job.checking_index]
                if row then
                    self:_place_capture_row(job, row, job.checking_index, self.checking_list)
                    if row.id == self.selected_paint_id then job.detail_row = row end
                    job.checking_index, job.paint_done = job.checking_index + 1, job.paint_done + 1
                    return
                end
            end
        end
        job.phase = "details"
    elseif job.phase == "details" then
        job.phase = "finish"
        return
    elseif job.phase == "finish" then
        job.old_tiles, job.keep = nil, nil
        job.cache.ready, job.cache.job, job.cache.result = true, nil, job
        job.cache.membership_revision = job.membership_revision or 0
        if not job.background then
            if job.patch then self:_bind_cached_controls(job.cache) end
            self:_show_cached_summary(job.cache)
            if not self:_paint_cache_current(job.cache, job.generation, job.model) or self.render_job ~= job then
                job.phase = "done"
                return
            end
            self:_update_diagnostics()
            if self:_paint_cache_current(job.cache, job.generation, job.model) and self.render_job == job then
                self.full_render_model = job.model
            end
        end
        if self:_paint_cache_current(job.cache, job.generation, job.model) and self.render_job == job and job.cache.ready then
            job.cache.scroll:SetVisibility(0) -- Publish the completed page in one native change.
            if not job.background then self:_paint_page_shown(job.cache, false) end
            if job.cache.restore_scroll then
                job.cache.scroll:SetScrollOffset(job.cache.restore_scroll)
                job.cache.restore_scroll = nil
            end
        end
        job.phase = "done"
    end
end

local STOCK_FIELDS = { "count", "complete", "stockSourcesComplete", "stockWitnesses", "stockLocationHints", "stockSources" }
local STOCK_MODEL_FIELDS = { "status", "cachePreview", "physicalCount", "sourceCount", "includedSourceCount",
    "stockSourcesComplete", "stockLocationSources", "stockRadiusCm", "stockScope", "capturedUtc",
    "backpackCounts", "backpackPhysicalCount", "combinedPhysicalCount" }

-- Snapshot rows contain only this verification interval's contributions. Old
-- disk observations must arrive as cachePreview/unknown, never lower bounds.
-- An unfinished patch finishes its bounded native walk before the newest
-- pending snapshot starts, so frequent reads cannot starve later tiles.
function M:update_stock(snapshot)
    local model = self.model
    if type(snapshot) ~= "table" or not model or snapshot.contextToken ~= model.contextToken
        or type(snapshot.rows) ~= "table" or #snapshot.rows > (self.config.max_catalog or 512) then return false end
    local fields = {}
    for _, key in ipairs(STOCK_MODEL_FIELDS) do fields[key] = snapshot[key] end
    local pending = { source = snapshot.rows, fields = fields, complete = snapshot.stockComplete == true,
        previous = { status = model.status, cachePreview = model.cachePreview, stockComplete = model.stockComplete,
            backpackCounts = model.backpackCounts, _stockUiRevision = model._stockUiRevision } }
    self:_sync_stock_total(snapshot)
    model.stockComplete = false
    self:_sync_learn_all_enabled()
    if self.detail_learn_control and valid(self.detail_learn_control.widget) then
        self.detail_learn_control.widget:SetIsEnabled(false)
    end
    self.stock_patch_pending = pending
    if not self.stock_patch_job then self:_start_stock_patch() end
    return true
end

function M:_start_stock_patch()
    local pending = self.stock_patch_pending
    if not pending or not self.model then return end
    self.stock_patch_pending = nil
    self.stock_patch_serial = (self.stock_patch_serial or 0) + 1
    self.model._stockUiRevision = self.stock_patch_serial
    self.model.stockComplete = false
    self.model.cachePreview = pending.fields.cachePreview == true
    self.stock_patch_job = { model = self.model, source = pending.source, fields = pending.fields,
        complete = pending.complete, revision = self.stock_patch_serial, phase = "source", index = 1,
        previous = pending.previous, projection_changed = not self.paint_projection or self.paint_projection.sorted ~= nil,
        measured = { status = pending.fields.status, cachePreview = pending.fields.cachePreview, stockComplete = pending.complete,
            backpackCounts = pending.fields.backpackCounts, _stockUiRevision = self.stock_patch_serial },
        by_id = {}, categories = { learned = 0, ready = 0, missing = 0, checking = 0 },
        tabs = { self.active_paint_cache, self.paint_caches and self.paint_caches.learned,
            self.paint_caches and self.paint_caches.ready, self.paint_caches and self.paint_caches.missing },
        seen_tabs = {}, tab_index = 1, tile_index = 1 }
end

function M:_patch_stock_entry(entry, job)
    local function current()
        return self.open and self.model == job.model and (job.patch and self.render_job == job
            or self.stock_patch_job == job and job.model._stockUiRevision == job.revision)
    end
    if not current() or not entry or not valid(entry.count) then return end
    local row, model = entry.row, job.model
    local caption = stock_caption(model, row)
    if entry.caption ~= caption then
        self:_set_text(entry.count, caption)
        entry.caption = caption
    end
    if not current() then return end
    local absent = measured_stock(model, row) and paint_view.physical_count(model, row) == 0
    local description = paint_tooltip(row, caption, absent)
    if entry.description ~= description then
        self:_set_text(entry.tooltip_label, description)
        entry.description = description
    end
    if not current() then return end
    if absent ~= entry.absent then
        if valid(entry.image) then
            entry.image:SetIsEnabled(not absent)
            if not current() then return end
        end
        if valid(entry.decoration or entry.image) then
            (entry.decoration or entry.image):SetRenderOpacity(absent and absent_opacity(self.config) or 1)
        end
    end
    if not current() then return end
    entry.absent = absent
    entry.mark = paint_view.classify(model, row)
end

function M:_pump_stock(budget)
    if self.active_tab == "presets" then return end
    if self.pending_backpack and not self.capture_patch and not self.stock_patch_job and not self.stock_patch_pending then
        local pending = self.pending_backpack
        self.pending_backpack = nil
        self:update_backpack_counts(pending.token, pending.counts)
    end
    local batching = processing.batching_enabled()
    local limit = batching and processing.get("unit_limit_enabled", true)
        and processing.get("work_units_per_tick", self.config.work_units_per_tick or 8) or math.huge
    local native_limit = batching and processing.get("ui_stock_items_per_tick", self.config.ui_rows_per_tick or 2) or math.huge
    local rows = processing.get("ui_stock_rows_per_unit", 32)
    local native = 0
    for _ = 1, limit do
        local job = self.stock_patch_job
        if not job or not self.open or job.model ~= self.model or budget and budget:expired() then return end
        if job.phase == "source" then
            for _ = 1, rows do
                local row = job.source[job.index]
                if not row then job.phase, job.index = "rows", 1; break end
                if type(row.id) == "string" then
                    local copy = {}
                    for _, key in ipairs(STOCK_FIELDS) do copy[key] = row[key] end
                    job.by_id[row.id] = copy
                end
                job.index = job.index + 1
            end
        elseif job.phase == "rows" then
            for _ = 1, rows do
                local row = job.model.rows[job.index]
                if not row then
                    for _, key in ipairs(STOCK_MODEL_FIELDS) do job.model[key] = job.fields[key] end
                    job.model.stockComplete = job.complete and not self.stock_patch_pending
                    job.phase = "tiles"
                    break
                end
                local source = job.by_id[row.id]
                local previous_category = paint_view.classify(job.previous, row)
                local count_sort = self.view.sort == "count_asc" or self.view.sort == "count_desc"
                local previous_count = count_sort and paint_view.physical_count(job.previous, row)
                for _, key in ipairs(STOCK_FIELDS) do
                    if source then row[key] = source[key] else row[key] = nil end
                end
                if not source then row.complete = false; job.complete = false end
                row._stockUiRevision = job.revision
                local category = paint_view.classify(job.measured, row)
                if category ~= previous_category or count_sort and paint_view.physical_count(job.measured, row) ~= previous_count then
                    job.projection_changed = true
                end
                job.categories[category] = job.categories[category] + 1
                job.index = job.index + 1
            end
        elseif job.phase == "tiles" then
            if native >= native_limit then return end
            local cache = job.tabs[job.tab_index]
            if not cache then job.phase = "finish"
            elseif job.seen_tabs[cache] then job.tab_index, job.tile_index = job.tab_index + 1, 1
            else
                local entry = (cache.visible_tiles or {})[job.tile_index]
                if entry then self:_patch_stock_entry(entry, job); job.tile_index = job.tile_index + 1; native = native + 1
                else job.seen_tabs[cache] = true; job.tab_index, job.tile_index = job.tab_index + 1, 1 end
            end
        else
            if native >= native_limit then return end
            if self.detail_row then self:_render_details(self.detail_row, job.model) end
            if self.stock_patch_job ~= job or self.model ~= job.model or not self.open then return end
            self:_set_text(self.stock_radius_label, self:_stock_radius_caption(job.model))
            if self.stock_patch_job ~= job or self.model ~= job.model or not self.open then return end
            if job.complete and job.model.stockComplete then
                if self.paint_projection then
                    self.paint_projection.category_counts = job.categories
                    self.paint_projection.ready_count = job.categories.ready
                end
                self.category_counts = job.categories
                for _, cache in pairs(self.paint_caches or {}) do
                    if cache.result then cache.result.category_counts, cache.result.ready_count = job.categories, job.categories.ready end
                end
                for tab, control in pairs(self.tab_controls or {}) do
                    if PAINT_TABS[tab] then update_tab_count(self, tab, control, job.categories) end
                end
                self.learn_all_ready_count = job.categories.ready
            end
            self:_sync_learn_all_enabled()
            self.stock_patch_job = nil
            if job.complete and job.model.stockComplete and job.projection_changed then
                self:_queue_render(job.model, true, false, true)
            end
            self:_start_stock_patch()
        end
        if budget then budget:consume(1) end
    end
end

-- One immutable result from the opening's completed Vault pass. Collection
-- supplies only native-confirmed learned identities, without stock evidence.
function M:show_learned(snapshot, retained_source)
    if not self.open or self.active_tab ~= "learned" or not self:is_connected()
        or type(snapshot) ~= "table" or snapshot.learnedOnly ~= true or snapshot.stockComplete ~= false then return false end
    if self.model then
        if self.model.contextToken ~= snapshot.contextToken or not retained_source
            or self.capture_source ~= retained_source and self.model ~= retained_source then return false end
        self.waiting_stock = true
        self:reconcile_capture(snapshot, retained_source)
    else self:set_model(snapshot, true) end
    return true
end

function M:reconcile_capture(captured, retained_source)
    if languages.game_tag and captured and (captured.paintNameRevision ~= languages.game_revision
        or self.model and self.model.paintNameRevision ~= languages.game_revision) then
        self:set_model(captured, retained_source ~= nil)
        return
    end
    if not self.open or not self.model or not captured or self.model.contextToken ~= captured.contextToken then
        self:set_model(captured)
        return
    end
    self.capture_patch = { source = retained_source or captured, learned_overlay = retained_source ~= nil,
        prepare = paint_view.begin_capture(self.model, captured, self.paint_projection,
        { query = self.view.query, sort = self.view.sort, favorites = self.favorites }, self.config.max_catalog or 512, retained_source ~= nil),
        previous = self.paint_projection }
    self:_sync_learn_all_enabled()
    if self.detail_learn_control then self.detail_learn_control.widget:SetIsEnabled(false) end
end

function M:_advance_capture_patch(budget)
    local pending = self.capture_patch
    local progress = plain_work.run(function()
        local ok, model, projection = coroutine.resume(pending.prepare)
        if not ok then error(model) end
        if model then return { state = "done", model = model, projection = projection } end
        return { state = "running" }
    end, budget, { group = "projection_primitives" })
    if budget and progress then budget:consume(1) end
    if not progress or progress.state ~= "done" then return end
    self.capture_patch = nil
    self.waiting_stock = pending.learned_overlay
    if pending.learned_overlay and progress.model == self.model then return end
    if not progress.projection or pending.previous ~= self.paint_projection then
        self:set_model(progress.model, pending.learned_overlay)
        self.capture_source = pending.source
        return
    end
    self.stock_patch_job, self.stock_patch_pending = nil, nil
    self.model, self.paint_projection = progress.model, progress.projection
    self:_sync_stock_total(self.model)
    self.capture_source = pending.source
    self.render_generation = (self.render_generation or 0) + 1
    self:_set_learn_all_ready(self.model, self.render_generation, 0)
    self:_clear_learn_buttons()
    self.render_job = nil
    for _, cache in pairs(self.paint_caches) do
        cache.patch_existing, cache.ready = cache.ready, false
        cache.job, cache.result = nil, nil
        cache.membership_revision = self.membership_revision or 0
    end
    if PAINT_TABS[self.active_tab] then
        self.render_job = self:_new_render_job(self.active_paint_cache)
        self.active_paint_cache.job = self.render_job
    end
end

function M:set_model(model, waiting_stock)
    if model ~= self.model or not model or waiting_stock ~= nil then self.waiting_stock = waiting_stock end
    self.capture_patch = nil
    if not model or model ~= self.model then self.reopen_view = nil end
    if not model or model ~= self.model or not self.capture_source then self.capture_source = model end
    self.stock_patch_job, self.stock_patch_pending = nil, nil
    if not model or self.model and self.model.contextToken ~= model.contextToken then self.selected_paint_id = nil end
    self.model = model
    self.full_render_model = nil
    self:_queue_render(model, false)
end

function M:_queue_render(model, paint_only, reuse_projection, patch_existing)
    self:_sync_stock_total(model)
    self.render_generation = (self.render_generation or 0) + 1
    self:_set_learn_all_ready(model, self.render_generation, 0)
    self:_clear_learn_buttons()
    self.render_job = nil
    if not reuse_projection then
        if self.projection_job then self.projection_job:cancel() end
        self.projection_job, self.paint_projection = nil, nil
    end
    for _, cache in pairs(self.paint_caches or {}) do
        if not reuse_projection or cache == self.active_paint_cache then
            cache.patch_existing = patch_existing and (cache.ready or cache.patch_existing)
            if cache.patch_existing and cache == self.active_paint_cache then cache.ready = false
            else self:_conceal_paint_cache(cache) end
            cache.job, cache.result = nil, nil
            if not reuse_projection and not patch_existing and cache ~= self.active_paint_cache then cache.offset = 0 end
        end
    end
    if not self.root or not PAINT_TABS[self.active_tab] then return end
    local cache = self.paint_caches[self.active_tab]
    self.active_paint_cache = cache
    cache.offset, cache.selected, cache.checking_expanded = self.page_offset, self.selected_paint_id, self.checking_expanded
    if not self.paint_projection and not self.projection_job then
        self.projection_favorite_revision = self.favorite_order_revision or 0
        self.projection_job = paint_view.begin(model, { query = self.view.query, filter = "all", sort = self.view.sort,
            favorites = self.favorites, include_groups = false, full_catalog = true,
            max_catalog = self.config.max_catalog or 512, generation = self.render_generation })
    end
    self.render_job = self:_new_render_job(cache)
    self.render_job.view_job = self.projection_job
    cache.job = self.render_job
end

function M:is_rendering()
    if self.active_tab == "presets" then return self.preset_render_job ~= nil end
    return self.capture_patch ~= nil or self.render_job ~= nil and not self.render_job.background
end

function M:render_progress()
    local job = self.render_job and not self.render_job.background and self.render_job
    if self.active_tab == "presets" then job = self.preset_render_job end
    if self.capture_patch and self.active_tab ~= "presets" then
        return { phase = "prepare", completed = 0, total = 0, generation = self.render_generation,
            presentation = { phase = "render", mode = "indeterminate", unit = "tiles", coverage = "unknown" } }
    end
    if not job then return self.last_render_progress or { phase = "idle", completed = 0, total = 0 } end
    local presentation = { phase = "render", mode = "indeterminate", unit = "tiles", coverage = "unknown" }
    if job.phase == "paints" or job.phase == "checking" then
        local total = #(job.rows or {}) + (self.checking_expanded and #(job.checking_rows or {}) or 0)
        if total > 0 then presentation.mode, presentation.total, presentation.completed = "determinate", total, job.paint_done or 0 end
    end
    return { phase = job.phase, completed = job.completed, total = job.total, generation = job.generation,
        paintRows = job.paint_done, presentation = presentation }
end

-- An actual game-language change can arrive during a stock capture or while a
-- completed page is open. Resolve only known, resident paints in the existing
-- UI budget. Never enumerate inventory or modify the captured gameplay model.
function M:_refresh_native_paint_names(budget)
    local revision = languages.game_revision
    if not languages.game_tag then return false end
    if self.name_revision ~= revision then
        self.name_revision, self.name_refresh = revision, nil
        local source = self.capture_patch and self.capture_patch.source or self.capture_source or self.model
        if source and source.paintNameRevision ~= revision then self:set_model(source, self.waiting_stock) end
        if self.preset_list then self:_queue_preset_render() end
    end
    local source = self.model
    if not source or source.paintNameRevision == revision then self.name_refresh = nil; return false end
    if not PAINT_TABS[self.active_tab] or not self:is_connected() then return self.active_tab ~= "presets" end
    local job = self.name_refresh
    if not job or job.source ~= source then
        local view = {}
        for key, value in pairs(source) do view[key] = value end
        view.rows, view.paintNameRevision = {}, revision
        job = { source = source, view = view }
        self.name_refresh = job
    end
    local limit = processing.get("ui_rows_per_tick", self.config.ui_rows_per_tick or 2)
    for _ = 1, limit do
        if budget and budget:expired() then return true end
        local row = source.rows and source.rows[#job.view.rows + 1]
        if not row then
            self.name_refresh = nil
            self:set_model(job.view, self.waiting_stock)
            self.capture_source = source
            return true
        end
        local copy = {}
        for key, value in pairs(row) do copy[key] = value end
        local _, name = collection.loaded_paint_icon(row.assetType, row.assetName)
        copy.displayName, copy.nameAvailable = name, name ~= nil
        copy.paintNameLanguage = languages.game_tag
        job.view.rows[#job.view.rows + 1] = copy
        if budget then budget:consume(1) end
    end
    return true
end

function M:_pump_render(budget)
    if self:_refresh_native_paint_names(budget) then return end
    if self.active_tab == "presets" and not self.preset_render_job then return end
    if self.capture_patch and self.active_tab ~= "presets" then self:_advance_capture_patch(budget) end
    if self.render_job and self.render_job.membership_stale then
        self:_conceal_paint_cache(self.render_job.cache)
        self.render_job.cache.job = nil
        self.render_job = nil
    end
    self:_prewarm_paint_tab()
    local function local_clock()
        local ok, value = pcall(function() return os.clock() end)
        if ok and type(value) == "number" and value == value and math.abs(value) ~= math.huge then return value end
    end
    local started = not budget and local_clock() or nil
    local batching = processing.batching_enabled()
    local row_limit = batching and processing.get("ui_rows_per_tick", self.config.ui_rows_per_tick or 2) or math.huge
    local limit = batching and processing.get("unit_limit_enabled", true)
        and math.max(row_limit, processing.get("work_units_per_tick", self.config.work_units_per_tick or 8)) or math.huge
    local native_items = 0
    local function expired()
        if budget then return budget:expired() end
        if not batching or not processing.get("time_limit_enabled", true) or not started then return false end
        local now = local_clock()
        if not now then started = nil; return false end
        return (now - started) * 1000 >= processing.work_target_ms(self:is_open(), self.config)
    end
    for _ = 1, limit do
        local use_preset = self.active_tab == "presets"
        local job = self.render_job
        if use_preset then job = self.preset_render_job end
        local generation = use_preset and self.preset_generation or self.render_generation
        if not job or job.generation ~= generation or expired() then return end
        if job.phase ~= "prepare" then
            if native_items >= row_limit then return end
            native_items = native_items + 1
        end
        job.worker_defer=false
        if use_preset then self:_advance_preset_render(job,budget) else
            local active = self.active_paint_cache
            if active then self:_save_paint_cache(active) end
            self.building_paint_cache = job.cache
            self:_use_paint_cache(job.cache)
            self:_advance_render(job,budget)
            self:_save_paint_cache(job.cache)
            self.building_paint_cache = nil
            if active and active ~= job.cache then self:_use_paint_cache(active) end
        end
        job.completed = job.completed + 1
        if use_preset then
            if self.preset_render_job == job and job.generation == self.preset_generation then
                if job.phase == "done" then
                    job.total = job.completed
                    if not self.render_job or self.render_job.background then self.last_render_progress = self:render_progress() end
                    self.preset_render_job = nil
                end
            end
        elseif self.render_job == job and job.generation == self.render_generation then
            if job.phase == "done" then
                job.total = job.completed
                self.last_render_progress = self:render_progress()
                self.render_job = nil
            else
                -- Internal scheduling units are deliberately not shown as a
                -- user-facing overall loading percentage.
            end
        end
        if budget then budget:consume(1) end
        if job.worker_defer then return end
        if not self.render_job then self:_prewarm_paint_tab() end
    end
end

local function status_line(status)
    local labels = { queued = "ui.status.queued", running = "ui.status.running", done = "ui.status.done", error = "ui.status.error", cancelled = "ui.status.cancelled" }
    local commands = { refresh = "ui.button.refresh", snapshot = "ui.button.snapshot", discovery = "ui.button.discovery",
        jmap = "ui.command.jmap", learn_recipe = "ui.button.learn_recipe", learn_all = "ui.button.learn_all",
        preset_refresh = "ui.preset.refresh", preset_save = "ui.preset.save", preset_apply = "ui.preset.apply",
        preset_import = "ui.storage.import", preset_delete = "ui.preset.delete", preferences = "ui.command.preferences",
        toggle = "ui.command.window", ui = "ui.command.window" }
    local transfer = TRANSFER_ICONS[status.command] ~= nil
    local transfer_key = transfer and "ui.transfer." .. status.command
    local command = status.command and (transfer and t(transfer_key)
        or t(commands[status.command] or "ui.command.task")) or nil
    local detail = status.reasonKey and t(status.reasonKey, status.reasonValues) or status.renderMessage and status.renderMessage() or status.message
    return t("ui.status.line", { state = labels[status.state] and t(labels[status.state]) or "",
        command = command and t("ui.status.command", { command = command }) or "",
        message = (transfer or status.state == "error") and tostring(detail or "") or "" })
end

function M:_render_status()
    local status = self.status or {}
    local line = status_line(status)
    local transfer = TRANSFER_ICONS[status.command] ~= nil
    if transfer then self.last_transfer_status, self.last_transfer_line = status, line
    elseif self.last_transfer_status then self.last_transfer_line = status_line(self.last_transfer_status) end
    self:_set_text(self.status_label, line)
    if self.transfer_result_label then
        self:_set_text(self.transfer_result_label, self.last_transfer_line)
        self.transfer_result_label:SetVisibility(self.last_transfer_line and not transfer and 0 or 1)
    end
    if self.signal_transfer_status then
        self:_set_text(self.signal_transfer_status, self.last_transfer_line)
        self.signal_transfer_status:SetVisibility(self.last_transfer_line and 0 or 1)
    end
    local report_path = status.path or self.debug_report_path
    if valid(self.path_label) then
        self:_set_text(self.path_label, report_path and t("ui.status.report", { path = report_path }) or "")
        self.path_label:SetVisibility(report_path and 0 or 1)
    end
end

function M:set_status(status)
    self.status = status or {}
    if self.status.reasonKey and self.status.message == nil then
        self.status.message = t(self.status.reasonKey, self.status.reasonValues)
    end
    if self.status.path and (self.status.command == "snapshot" or self.status.command == "discovery" or self.status.command == "jmap") then
        self.debug_report_path = self.status.path
    end
    if self.preset_pending and self.status.command == "preset_save"
        and (self.status.state == "error" or self.status.state == "cancelled") then self:_remove_pending_preset() end
    self:_render_status()
    self:_tab_load_stopped()
end

-- Input ownership is recorded before any native call. Each ignore-input claim is
-- balanced exactly once; other mods' ignore counters are never globally reset.
function M:_capture_input()
    self.input_claimed = true
    self.previous_cursor = self.pc.bShowMouseCursor == true
    self.move_claim = true
    self.pc:SetIgnoreMoveInput(true)
    self.look_claim = true
    self.pc:SetIgnoreLookInput(true)
    self.pc.bShowMouseCursor = true
    self.input:SetInputMode_UIOnlyEx(self.pc, self.close_button, 0, true)
    self.close_button:SetKeyboardFocus()
end

function M:close(reason)
    if reason ~= "user" then self.debug_report_path = nil end
    if self.tab_click then self:_finish_tab_click(self.tab_click.tab, "closed") end
    self.preset_page_outcome = nil
    self.reopen_view = nil
    if reason == "user" and self.open and self.model and self.paint_caches then
        if self.active_paint_cache then self:_save_paint_cache(self.active_paint_cache) end
        local pages = {}
        for tab, cache in pairs(self.paint_caches) do
            local offset = cache.restore_scroll
            if cache.ready and valid(cache.scroll) then
                local ok, current = pcall(function() return cache.scroll:GetScrollOffset() end)
                if ok and type(current) == "number" and current >= 0 and current < math.huge then offset = current end
            end
            pages[tab] = { selected = cache.selected, offset = cache.offset, scroll = offset }
        end
        local projection = self.paint_projection
        self.reopen_view = { model = self.model, query = self.view.query, sort = self.view.sort, pages = pages,
            projection = projection and not projection.sorted and not projection.membership_dirty and not projection.stock_order_dirty and projection or nil }
    end
    self.open = false
    if self.manual_page and self.active_tab ~= "debug" then self.active_tab = self.preferences.lastPage end
    self.manual_page, self.pending_page = nil, nil
    self.last_page_summary = nil
    self.capture_patch = nil
    self.escape_pending = nil
    self.learning = false
    self.learn_all_ready_count = 0
    self.jmap_armed = false
    if self.icons and self.connection_illustration_target and type(self.icons.retire) == "function" then
        pcall(self.icons.retire, self.icons, self.connection_illustration_target)
    end
    self.connection_illustration_requested, self.connection_illustration_target, self.connection_illustration_error = nil, nil, nil
    if self.icons then
        if self.icons_shared then
            pcall(function() self.icons:release_targets() end)
        else pcall(function() self.icons:close() end) end
        self.icons, self.icons_shared = nil, nil
    end
    self.render_generation = (self.render_generation or 0) + 1
    if self.render_job and self.render_job.view_job then self.render_job.view_job:cancel() end
    self.render_job = nil
    self.preset_render_job = nil
    self.preset_generation = (self.preset_generation or 0) + 1
    self.full_render_model = nil
    self.stock_patch_job, self.stock_patch_pending, self.pending_backpack = nil, nil, nil
    self.last_render_progress = { phase = "cancelled", completed = 0, total = 0, generation = self.render_generation }
    local failures = {}
    local function attempt(fn)
        local ok, err = pcall(fn)
        if not ok then failures[#failures + 1] = tostring(err) end
        return ok
    end
    -- Return focus while the owned Slate tree is still alive and parented.
    -- A failed mode restoration keeps that tree for the next bounded retry.
    if self.input_claimed and valid(self.pc) then
        if self.move_claim and attempt(function() self.pc:SetIgnoreMoveInput(false) end) then self.move_claim = false end
        if self.look_claim and attempt(function() self.pc:SetIgnoreLookInput(false) end) then self.look_claim = false end
        local mode_ok = attempt(function() self.input:SetInputMode_GameOnly(self.pc, true) end)
        attempt(function() self.pc.bShowMouseCursor = self.previous_cursor == true end)
        if mode_ok then attempt(function() self.input:SetFocusToGameViewport() end) end
        if mode_ok and not self.move_claim and not self.look_claim then self.input_claimed = false end
    elseif not valid(self.pc) then
        self.input_claimed, self.move_claim, self.look_claim = false, false, false
    end
    local cleanup_root = self.root or self.cleanup_root
    local cleanup_host = self.host or self.cleanup_host
    local cleanup_tree = self.tree or self.cleanup_tree
    local cleanup_frame = self.frame or self.cleanup_frame
    self.cleanup_root, self.cleanup_host, self.cleanup_tree, self.cleanup_frame = nil, nil, nil, nil
    local removed = not valid(cleanup_host)
    if valid(cleanup_host) and not self.input_claimed then
        attempt(function() cleanup_host:SetVisibility(1) end)
        removed = attempt(function()
            cleanup_host:RemoveFromParent()
            assert(not cleanup_host:IsInViewport(), t("ui.error.host_not_removed"))
        end)
    end
    if valid(cleanup_frame) then
        attempt(function() cleanup_frame:SetVisibility(1) end)
    end
    -- Detach only our panel after removing its host. The host's native canvas
    -- and RootWidget pointer remain untouched; no default children are cleared.
    local cleared = true
    if removed and valid(cleanup_frame) then
        cleared = attempt(function() cleanup_frame:RemoveFromParent() end)
    end
    if not removed or not cleared then
        self.cleanup_root, self.cleanup_host, self.cleanup_tree, self.cleanup_frame = cleanup_root, cleanup_host, cleanup_tree, cleanup_frame
    end
    self.host, self.tree, self.root, self.frame, self.frame_slot, self.geometry_key = nil, nil, nil, nil, nil, nil
    self.panel_width, self.panel_height, self.grid_column_count = nil, nil, nil
    self.icon_physical_scale = nil
    self.paint_grid_box, self.checking_grid_box = nil, nil
    self.buttons, self.paint_list, self.checking_list, self.switcher = {}, nil, nil, nil
    self.paint_caches, self.paint_views, self.active_paint_cache, self.building_paint_cache = nil, nil, nil, nil
    self.paint_projection = nil
    if self.projection_job then self.projection_job:cancel() end
    self.projection_job = nil
    self.learn_all_control = nil
    self.transfer_controls, self.transfer_state, self.detail_backpack, self.backpack_caption, self.pending_backpack = nil, nil, nil, nil, nil
    self.signal_return, self.signal_transfer_status, self.detail_actions_box = nil, nil, nil
    self.transfer_result_label, self.last_transfer_line, self.last_transfer_status = nil, nil, nil
    if TRANSFER_ICONS[self.status.command] then self.status = { state = "done", message = t("ui.status.ready") } end
    self.category_counts = nil
    self.search_box, self.sort_control, self.filter_controls, self.view_summary, self.last_search_text = nil, nil, nil, nil, nil
    self.summary, self.status_label, self.path_label = nil, nil, nil
    self.stock_toolbar, self.stock_radius_label, self.settings_help_text, self.preset_detail_host = nil, nil, nil, nil
    self.stock_total_label, self.stock_total_caption = nil, nil
    self.close_button = nil
    self.settings_page, self.debug_page, self.presets_host, self.debug_tab, self.tab_controls = nil, nil, nil, nil, nil
    self:_release_debug()
    self.checkboxes, self.visible_tiles, self.visible_tiles_by_id, self.details = nil, nil, nil, nil
    self.detail_title, self.detail_description, self.detail_learn_control, self.detail_learn_box, self.detail_row = nil, nil, nil, nil, nil
    self.detail_preview, self.detail_image, self.detail_fallback = nil, nil, nil
    self.spinner, self.progress_bar, self.progress_label, self.progress = nil, nil, nil, nil
    self.previous_control, self.next_control, self.checking_button, self.checking_control = nil, nil, nil, nil
    self.density_control, self.settings_sort_control = nil, nil
    self.language_widgets, self.language_choices = nil, nil
    self.name_refresh = nil
    self.ship_radius_controls = nil
    self.quantity_controls, self.quantity_apply, self.quantity_entry = nil, nil, nil
    self.connection_panel, self.content_panel, self.connection_actions, self.connection_distance = nil, nil, nil, nil
    self.connection_description = nil
    self.connection_presentation = nil
    self.connection_illustration, self.connection_illustration_scale = nil, nil
    self.preset_list, self.preset_summary, self.preset_name_box, self.preset_controls, self.persistence_label = nil, nil, nil, nil, nil
    self.preset_notice, self.preset_heading_zones, self.preset_save_row, self.preset_save_icons = nil, nil, nil, nil
    self.preset_details_box, self.preset_icon_box, self.preset_preview_box, self.preset_apply_box = nil, nil, nil, nil
    self.preset_detail_title, self.preset_detail_zones, self.preset_detail_note, self.preset_delete_box = nil, nil, nil, nil
    self.preset_rows, self.preset_projection, self.preset_detail_ready, self.preset_action_width = nil, nil, nil, nil
    self.preset_refresh_control, self.preset_refresh_box = nil, nil
    self.preset_scroll, self.preset_pending, self.preset_reconciling = nil, nil, nil
    self.preset_view, self.preset_auto_requested, self.selected_preset_id = nil, nil, nil
    if reason ~= "user" then self.preset_selected_ids = nil end
    if reason ~= "user" then self.model, self.selected_paint_id, self.capture_source = nil, nil, nil end
    -- Retry failures only in the original world/controller/pawn context. A Lua
    -- proxy is not a lifetime owner; old-world handles must never be reused.
    local same_context = self.context_key ~= nil and current_context_key() == self.context_key
    if not same_context then
        self.cleanup_root, self.cleanup_host, self.cleanup_tree, self.cleanup_frame = nil, nil, nil, nil
        self.input_claimed, self.move_claim, self.look_claim = false, false, false
    end
    if not self.input_claimed then
        self.pc, self.layout, self.input = nil, nil, nil
    end
    if not self.input_claimed and self.cleanup_host == nil and self.cleanup_tree == nil and self.cleanup_root == nil and self.cleanup_frame == nil then
        self.context_key = nil
    end
    if #failures > 0 then
        self.status = { state = "error", message = t("ui.error.close", { errors = table.concat(failures, "; ") }),
            reasonKey = "main.error.render_failed" }
        if self.callbacks.log then self.callbacks.log(self.status.message) end
        return false, self.status.message
    end
    return true
end

function M:shutdown(reason)
    self:close(reason or "Mod unloading")
end

function M:toggle(wait_for_stock)
    if self.open then self:close("user"); return false end
    if self.input_claimed or self.cleanup_host or self.cleanup_tree or self.cleanup_root or self.cleanup_frame then
        local restored, err = self:close("retry")
        if not restored then return false, err end
    end
    self.waiting_stock = wait_for_stock == true
    local ok, err = pcall(function()
        self.pc = current_controller()
        self.context_key = context_key(self.pc)
        assert(self.context_key, t("ui.error.world_unavailable"))
        assert(self.pc.bShowMouseCursor ~= true, t("ui.error.menu_open"))
        local gameplay = StaticFindObject("/Script/Engine.Default__GameplayStatics")
        if valid(gameplay) then assert(not gameplay:IsGamePaused(self.pc), t("ui.error.pause_open")) end
        self.layout = StaticFindObject("/Script/UMG.Default__WidgetLayoutLibrary")
        self.input = StaticFindObject("/Script/UMG.Default__WidgetBlueprintLibrary")
        assert(valid(self.layout) and valid(self.input), t("ui.error.services_unavailable"))
        self.host = self.input:Create(self.pc, host_class(), self.pc)
        assert(valid(self.host), t("ui.error.host_creation"))
        self.tree = self.host.WidgetTree
        assert(valid(self.tree), t("ui.error.tree_unavailable"))
        assert(same_object(self.tree:GetOuter(), self.host), t("ui.error.tree_ownership"))
        self.root = self.tree.RootWidget
        assert(valid(self.root) and self.root:IsA("/Script/UMG.CanvasPanel"), t("ui.error.root_unavailable"))
        assert(same_object(self.root:GetOuter(), self.tree), t("ui.error.root_ownership"))
        self:_build()
        self.host:SetVisibility(4)
        self.host:AddToViewport(9800)
        self:_fit()
        self:_capture_input()
        self.open = true
        self:_sync_transfer_controls()
    end)
    if not ok then
        self:close("error")
        self.status = { state = "error", message = tostring(err), reasonKey = player_messages.reason_key(err, "main.error.render_failed") }
        return false, tostring(err)
    end
    return true
end

function M:_pump_icons(budget)
    if not self.icons or self.active_tab == "presets" and self:is_connected() then return end
    -- Startup preparation has its own bounded idle allowance. Visible row
    -- construction retains priority, even with an unusually large budget.
    local used = 0
    local maximum = processing.batching_enabled() and processing.get("ui_icon_units", 1) or math.huge
    self.icons:pump({
        expired = function() return used >= maximum or budget and budget:expired() or false end,
        consume = function(_, units)
            used = used + (units or 1)
            if budget then budget:consume(units) end
        end,
    })
end

-- The controller polls input before admitting cache/collection work. Rendering
-- then shares the remaining budget without delaying close/button handling.
function M:render_tick(budget)
    if not self.open or self.escape_pending then return end
    local ok, err = pcall(function()
        self:_pump_stock(budget)
        self:_pump_render(budget)
        self:_pump_icons(budget)
    end)
    if not ok then
        self:close("error")
        self.status = { state = "error", message = tostring(err), reasonKey = player_messages.reason_key(err, "main.error.render_failed") }
        if self.callbacks.log then self.callbacks.log(t("ui.log.error", { error = tostring(err) })) end
    end
end

local function pressed_once(button)
    local down = button.widget:IsPressed() == true
    if not down then button.release_required = false end
    local fire = down and not button.pressed and not button.release_required and button.widget:GetIsEnabled()
    button.pressed = down
    return fire
end

function M:tick(budget, input_only)
    if not self.open then
        if self.input_claimed or self.cleanup_host or self.cleanup_tree or self.cleanup_root or self.cleanup_frame then
            if self.context_key ~= current_context_key() then
                -- A pending retry belongs to an old world. Do not dereference
                -- its saved proxies after a context transition.
                self.cleanup_host, self.cleanup_tree, self.cleanup_root, self.cleanup_frame = nil, nil, nil, nil
                self.pc, self.layout, self.input, self.context_key = nil, nil, nil, nil
                self.input_claimed, self.move_claim, self.look_claim = false, false, false
                self.model = nil
            else self:close("retry") end
        end
        return
    end
    local ok, err = pcall(function()
        assert(valid(self.pc), t("ui.error.controller_invalid"))
        assert(valid(self.host), t("ui.error.host_invalid"))
        assert(valid(self.tree), t("ui.error.tree_invalid"))
        assert(valid(self.root), t("ui.error.root_invalid"))
        assert(valid(self.frame), t("ui.error.frame_invalid"))
        assert(same_object(self.tree.RootWidget, self.root), t("ui.error.root_changed"))
        if self.pc.bShowMouseCursor ~= true or not self.host:IsInViewport() then
            self:close("input_changed")
            return
        end
        if self.escape_pending then
            self:close("user")
            return
        end
        if self.language_revision ~= messages.revision then self:refresh_language() end
        self:_fit()
        if not self:is_connected() then
            local button = self.buttons[1]
            if button and button.connection_close and pressed_once(button) then button.action(); return end
            if self.signal_return and self.signal_return.shown and pressed_once(self.signal_return) then
                self.signal_return.action()
                return
            end
            if not input_only then self:_pump_stock(budget); self:_pump_render(budget); self:_pump_icons(budget) end
            return
        end
        self:_poll_search()
        if self.active_tab == "debug" and self.debug_section == "processing" then self:_poll_processing_editor() end
        for _, button in ipairs(self.buttons) do
            local active = button.scope == nil or button.scope == self.active_tab or button.scope == "paint" and PAINT_TABS[self.active_tab]
            if button.scope == "debug" and not self.preferences.showDeveloperTools then active = false end
            if button.debug_section and button.debug_section ~= self.debug_section then active = false end
            if button.processing_group and button.processing_group ~= self.processing_group then active = false end
            if button.paint_cache and button.paint_cache ~= self.active_paint_cache then active = false end
            if button.paint_cache and not button.paint_cache.ready then active = false end
            if button.transfer and not button.shown then active = false end
            if not active then
                -- Hidden tabs can contain hundreds of native row buttons.
                -- Keep their polling out of mandatory input housekeeping, but
                -- retain a held press until an active release is observed.
                button.release_required = button.release_required or button.pressed == true
                button.pressed = false
            else
                local fire = pressed_once(button)
                    and ((button.kind ~= "learn_recipe" and button.kind ~= "learn_all") or not self.learning)
                if fire then
                    button.action()
                    -- Actions can change the view or close the window.
                    return
                end
            end
        end
        for key, record in pairs(self.checkboxes or {}) do
            if record.scope == self.active_tab and valid(record.widget) then
                local checked = record.widget:IsChecked() == true
                if checked ~= record.checked then
                    if not self:_change_settings({ [key] = checked }) then record.widget:SetIsChecked(record.checked) end
                    return
                end
            end
        end
        if not input_only then
            self:_pump_stock(budget)
            self:_pump_render(budget)
            self:_pump_icons(budget)
        end
    end)
    if not ok then
        self:close("error")
        self.status = { state = "error", message = tostring(err), reasonKey = player_messages.reason_key(err, "main.error.render_failed") }
        if self.callbacks.log then self.callbacks.log(t("ui.log.error", { error = tostring(err) })) end
    end
end

require("paintmanager.ui_processing")(M, valid, C)
require("paintmanager.ui_debug")(M, valid, C)
return M
